"Der Restbruch strebt für {0} gegen {1} (Zählergrad {2} Nennergrad):": "Zbývající zlomek se pro {0} blíží k {1} (stupeň čitatele {2} stupeň jmenovatele):",
"Der Schnittpunkt des Graphen mit der y-Achse. Er wird berechnet, indem x = {0} in {1} eingesetzt wird. Existiert immer, wenn {2} ∈ D.": "Průsečík grafu s osou y. Vypočítá se dosazením x = {0} do {1}. Existuje vždy, pokud {2} ∈ D.",
"Der Wert {0} liegt ausserhalb von {1} — {2} nimmt ihn nie an: <3>keine Lösung</3>.": "Hodnota {0} leží mimo {1} — {2} ji nikdy nenabývá: <3>žádné řešení</3>.",
"Der Zähler ist {0}, der Nenner ist {1} ⇒ <2>Polstelle</2> bei {3}.": "Čitatel je {0}, jmenovatel je {1} ⇒ <2>pól</2> v {3}.",
