"Die <0>Diskriminante</0> ist {1} mit {2} — zwei Lösungen:": "<0>Diskriminant</0> je {1}, {2} — dvě řešení:",
"Die <0>Diskriminante</0> ist {1} — zwei Lösungen:": "<0>Diskriminant</0> je {1} — dvě řešení:",
"Die <0>Diskriminante</0> ist {1}: genau eine (doppelte) Lösung.": "<0>Diskriminant</0> je {1}: právě jedno (dvojnásobné) řešení.",
"Die <0>Diskriminante</0> {1} ist negativ — <2>keine reelle Lösung</2>.": "<0>Diskriminant</0> {1} je záporný — <2>žádné reálné řešení</2>.",
"Die Ableitung konnte nicht gebildet werden.": "Derivaci se nepodařilo vytvořit.",
"Die Funktion ist eine Summe — jeden Summanden einzeln betrachten:": "Funkce je součet — posuďte každý sčítanec zvlášť:",
"Die Gerade ist waagrecht (m = {0}) — die Senkrechte dazu wäre eine senkrechte Linie x = … und lässt sich hier nicht als Funktion darstellen.": "Přímka je vodorovná (m = {0}) — kolmice by byla svislá přímka x = …, kterou zde nelze zobrazit jako funkci.",
"Die Gleichung ist ein Polynom in {0} — <1>Substitution</1> {2}:": "Rovnice je polynom v {0} — <1>substituce</1> {2}:",
"Die Gleichung {0} ist ein Widerspruch — <1>keine Lösung</1>.": "Rovnice {0} je spor — <1>žádné řešení</1>.",
"Die Grenzen a und b liegen genau übereinander — kein Intervall.": "Meze a a b leží přesně nad sebou — žádný interval.",
"Die Intervallgrenzen a und b liegen genau übereinander — kein Intervall.": "Hranice intervalu a a b leží přesně nad sebou — žádný interval.",
"Die Menge aller Punkte (x | {0}) in der Koordinatenebene, die zur Funktion f gehören. Der Graph veranschaulicht den Verlauf der Funktion.": "Množina všech bodů (x | {0}) v souřadnicové rovině, které patří funkci f. Graf znázorňuje průběh funkce.",
"Die Menge aller x-Werte, für die {0} definiert ist (existiert). Typische Einschränkungen: Nenner ≠ {1}, Radikand ≥ {2}, Argument des Logarithmus {3} {4}.": "Množina všech hodnot x, pro které je {0} definováno (existuje). Typická omezení: jmenovatel ≠ {1}, odmocněnec ≥ {2}, argument logaritmu {3} {4}.",
"Die Menge aller y-Werte, die {0} tatsächlich annimmt: W = {1}{2} | x ∈ D{3}. Nicht zu verwechseln mit dem Wertebereich (dem Zielbereich).": "Množina všech hodnot y, kterých {0} skutečně nabývá: H = {1}{2} | x ∈ D{3}. Nezaměňovat s kodoménou (cílovým oborem).",
"Die Strecke AB ist waagrecht (dy = {0}) — die Mittelsenkrechte dazu wäre eine senkrechte Linie x = … und lässt sich hier nicht als Funktion darstellen.": "Úsečka AB je vodorovná (dy = {0}) — její osa by byla svislá přímka x = …, kterou zde nelze zobrazit jako funkci.",
"Die Umkehrfunktion f⁻¹ «dreht» die Zuordnung um: sie ordnet jedem y-Wert wieder den ursprünglichen x-Wert zu. Existiert, wenn f streng monoton (bijektiv) ist. Graphisch: Spiegelung an der {0}. Winkelhalbierenden.": "Inverzní funkce f⁻¹ „obrací“ přiřazení: každé hodnotě y přiřadí zpět původní hodnotu x. Existuje, je-li f ryze monotónní (prostá). Graficky: zrcadlení podle {0}. osy kvadrantů.",
"Die Zielfunktion ist in diesem Bereich nicht beschränkt (unbeschränktes Gebiet) — bitte herauszoomen oder weitere Ungleichungen ergänzen.": "Účelová funkce není v této oblasti omezená (neomezená oblast) — oddalte prosím pohled nebo přidejte další nerovnice.",
"Die durchschnittliche Änderungsrate von f zwischen x und x+h. Geometrisch ist er die Steigung der Sekante durch (x | {0}) und (x+h | {1}).": "Průměrná rychlost změny f mezi x a x+h. Geometricky je to směrnice sečny body (x | {0}) a (x+h | {1}).",
"Die halbe Schwingungsbreite einer periodischen Funktion. Gibt an, wie weit der Graph maximal vom Mittelwert (Mittellinie) abweicht.": "Polovina rozkmitu periodické funkce. Udává, o kolik se graf maximálně odchyluje od střední hodnoty (střední přímky).",
"Die kleinste positive Zahl T, nach der sich der Funktionswert wiederholt: {0} = {1}. Für sin und cos: T = {2}π/b. Für tan: T = π/b.": "Nejmenší kladné číslo T, po kterém se funkční hodnota opakuje: {0} = {1}. Pro sin a cos: T = {2}π/b. Pro tan: T = π/b.",
"Die momentane Änderungsrate von f an der Stelle x. Geometrisch ist sie die Steigung der Tangente an den Graphen in (x | {0}). Wichtige Regeln: Potenzregel (xⁿ)'=n·xⁿ⁻¹, Summenregel, Produktregel, Kettenregel.": "Okamžitá změna funkce f v bodě x. Geometricky je to směrnice tečny ke grafu v (x | {0}). Důležitá pravidla: pravidlo pro mocninu (xⁿ)'=n·xⁿ⁻¹, pravidlo pro součet, pravidlo pro součin, řetězové pravidlo.",
"Diese Gleichung lässt sich <0>nicht</0> mit den üblichen Verfahren (Faktorisieren, Umkehrfunktion, Substitution) exakt nach {1} auflösen.": "Tuto rovnici <0>nelze</0> běžnými postupy (rozklad na součin, inverzní funkce, substituce) přesně vyřešit vzhledem k {1}.",
"Diese Gleichung lässt sich nicht exakt lösen. Der Wert ist eine <0>numerische Näherung</0> (≈).": "Tuto rovnici nelze vyřešit přesně. Hodnota je <0>numerické přiblížení</0> (≈).",
"Diese Nullstelle:": "Tento nulový bod:",
"Diese Nullstelle: {0} — wegen der Periodizität gibt es unendlich viele ({1}, {2}).": "Tento nulový bod: {0} — kvůli periodicitě jich existuje nekonečně mnoho ({1}, {2}).",
"Diese Nullstelle: {0} — wegen der Periodizität gibt es unendlich viele.": "Tento nulový bod: {0} — vzhledem k periodicitě jich je nekonečně mnoho.",
