"Eigener API-Schlüssel (Google Cloud, optional):": "Vlastní klíč API (Google Cloud, volitelné):",
"Ein Betrag ist nie negativ — <0>keine Lösung</0>.": "Absolutní hodnota nikdy není záporná — <0>žádné řešení</0>.",
"Ein Bruch ist genau dann {0}, wenn der <1>Zähler</1> {2} ist (und der Nenner {3}).": "Zlomek je roven {0} právě tehdy, když je <1>čitatel</1> roven {2} (a jmenovatel {3}).",
"Ein Bruch mit konstantem Zähler {0} wird nie {1} — <2>keine Lösung</2>.": "Zlomek s konstantním čitatelem {0} nikdy nenabude hodnoty {1} — <2>žádné řešení</2>.",
"Ein Graph ist auf einem Intervall konkav (nach unten offen, «Kuppel»), wenn die zweite Ableitung dort negativ ist. Jede Sekante liegt unter dem Graphen.": "Graf je na intervalu konkávní (otevřený dolů, „kupole“), je-li tam druhá derivace záporná. Každá sečna leží pod grafem.",
"Ein Graph ist auf einem Intervall konvex (nach oben offen, «Schüssel»), wenn die zweite Ableitung dort positiv ist. Jede Sekante liegt über dem Graphen.": "Graf je na intervalu konvexní (otevřený nahoru, „miska“), je-li zde druhá derivace kladná. Každá sečna leží nad grafem.",
"Ein Punkt (x₀ | {0}), in dem {1} grösser ist als alle benachbarten Funktionswerte. Notwendige Bedingung: {2} = {3}. Hinreichend: {4} {5} {6}.": "Bod (x₀ | {0}), v němž je {1} větší než všechny sousední funkční hodnoty. Nutná podmínka: {2} = {3}. Postačující: {4} {5} {6}.",
"Ein Punkt (x₀ | {0}), in dem {1} kleiner ist als alle benachbarten Funktionswerte. Notwendige Bedingung: {2} = {3}. Hinreichend: {4} {5} {6}.": "Bod (x₀ | {0}), ve kterém je {1} menší než všechny sousední funkční hodnoty. Nutná podmínka: {2} = {3}. Postačující: {4} {5} {6}.",
"Ein Quadrat ist nie negativ — die Gleichung hat <0>keine reelle Lösung</0>.": "Druhá mocnina nikdy není záporná — rovnice <0>nemá reálné řešení</0>.",
"Einblenden": "Zobrazit",
"Eine <0>Polstelle</0> (senkrechte Asymptote) liegt bei einer Nullstelle des <1>Nenners</1> vor, an der der Zähler <2>nicht</2> {3} ist.": "<0>Pól</0> (svislá asymptota) je v nulovém bodě <1>jmenovatele</1>, v němž čitatel <2>není</2> roven {3}.",
"Eine <0>hebbare Lücke</0> entsteht, wenn Zähler und Nenner an derselben Stelle {1} werden und sich der Faktor kürzen lässt.": "<0>Odstranitelná nespojitost</0> vzniká, když se čitatel i jmenovatel ve stejném bodě rovnají {1} a činitel lze zkrátit.",
"Eine <0>waagrechte Asymptote</0> entspricht dem Grenzwert für {1}.": "<0>Vodorovná asymptota</0> odpovídá limitě pro {1}.",
"Eine Exponentialfunktion mit positiver Basis ist stets positiv — {0} hat <1>keine Lösung</1>.": "Exponenciální funkce s kladným základem je vždy kladná — {0} <1>nemá řešení</1>.",
"Eine Funktion F, deren Ableitung die Ausgangsfunktion f ergibt. Ist nicht eindeutig: {0} + C ist ebenfalls eine Stammfunktion (C: Integrationskonstante). Grundregel: ∫xⁿdx = xⁿ⁺¹/(n+{1}) + C": "Funkce F, jejíž derivace je původní funkce f. Není jednoznačná: {0} + C je také primitivní funkce (C: integrační konstanta). Základní pravidlo: ∫xⁿdx = xⁿ⁺¹/(n+{1}) + C",
"Eine Funktion f ordnet jedem Element x der Definitionsmenge D genau ein Element {0} der Wertemenge W zu. Kein x-Wert darf zwei verschiedene y-Werte haben.": "Funkce f přiřazuje každému prvku x definičního oboru D právě jeden prvek {0} oboru hodnot H. Žádné x nesmí mít dvě různé hodnoty y.",
"Eine Funktion ist auf einem Intervall I monoton fallend, wenn grössere x-Werte kleinere (oder gleich grosse) Funktionswerte liefern. Bei streng monoton fallend gilt striktes {0}.": "Funkce je na intervalu I klesající, jestliže větší hodnoty x dávají menší (nebo stejné) funkční hodnoty. U ryze klesající funkce platí ostré {0}.",
"Eine Funktion ist auf einem Intervall I monoton steigend, wenn grössere x-Werte auch grössere (oder gleich grosse) Funktionswerte liefern. Bei streng monoton steigend gilt striktes {0}.": "Funkce je na intervalu I rostoucí, jestliže větší hodnoty x dávají také větší (nebo stejně velké) funkční hodnoty. U ryze rostoucí funkce platí ostrá nerovnost {0}.",
"Eine Funktion ist stetig in a, wenn der Grenzwert existiert und gleich dem Funktionswert {0} ist — keine Sprünge, Lücken oder Pole. Polynomfunktionen sind überall stetig.": "Funkce je spojitá v a, jestliže limita existuje a je rovna funkční hodnotě {0} — bez skoků, mezer nebo pólů. Polynomické funkce jsou spojité všude.",
"Eine Gerade, der sich der Graph beliebig nähert, ohne sie (in der Regel) zu erreichen. Es gibt vertikale, horizontale und schiefe Asymptoten.": "Přímka, ke které se graf libovolně přibližuje, aniž by jí (zpravidla) dosáhl. Existují svislé, vodorovné a šikmé asymptoty.",
"Eine Potenz ist nur dann {0}, wenn die Basis {1} ist: {2}.": "Mocnina je rovna {0} jen tehdy, když je základ {1}: {2}.",
"Eine Potenz mit negativem Exponenten wird nie {0} — <1>keine Lösung</1>.": "Mocnina se záporným exponentem nikdy nenabude hodnoty {0} — <1>žádné řešení</1>.",
"Eine Quadratwurzel ist nie negativ — <0>keine Lösung</0>.": "Druhá odmocnina nikdy není záporná — <0>žádné řešení</0>.",
"Eine Stelle x₀, an der der Funktionswert null ist. Der Graph schneidet (oder berührt) die x-Achse. Berechnung: {0} = {1} setzen und nach x auflösen.": "Bod x₀, ve kterém je funkční hodnota nulová. Graf protíná (nebo se dotýká) osy x. Výpočet: položit {0} = {1} a vyřešit vzhledem k x.",
"Eine Wurzel/Potenz mit gebrochenem Exponenten ist nie negativ — <0>keine Lösung</0>.": "Odmocnina/mocnina se zlomkovým exponentem nikdy není záporná — <0>žádné řešení</0>.",
"Eine gerade Potenz ist nie negativ — <0>keine Lösung</0>.": "Sudá mocnina nikdy není záporná — <0>žádné řešení</0>.",
"Eine gerade Potenz ist nie negativ — <0>keine reelle Lösung</0>.": "Sudá mocnina není nikdy záporná — <0>žádné reálné řešení</0>.",
"Eine nicht-waagrechte, nicht-senkrechte Gerade, der sich der Graph für x → ±∞ annähert. Tritt auf, wenn der Zählergrad genau um {0} grösser ist als der Nennergrad (Polynomdivision).": "Ani vodorovná, ani svislá přímka, ke které se graf přibližuje pro x → ±∞. Nastává, když je stupeň čitatele právě o {0} větší než stupeň jmenovatele (dělení polynomů).",
