"Endbestand {0} Anfangsbestand — das ist Wachstum, hier passt nur ein Wachstumsfaktor (b {1} {2}), kein Abnahmefaktor.": "Konečný stav {0} počáteční stav — jde o růst, vyhovuje jen růstový faktor (b {1} {2}), nikoli faktor poklesu.",
"Erhöhe n — O und U rücken näher an das exakte Integral heran.": "Zvyšte n — O a U se přibližují přesnému integrálu.",
