"Noch nichts konstruiert. Wähle ein Werkzeug und klicke in die Zeichenfläche, oder lade eine Vorlage.": "Zatím nic není sestrojeno. Vyberte nástroj a klikněte do kreslicí plochy, nebo načtěte šablonu.",
"Kein Begriff gefunden.": "Nebyl nalezen žádný pojem.",
