"Klicken: neuer Punkt (auf einer Linie oder einem Kreis wird er daran gebunden)": "Kliknutí: nový bod (na přímce nebo kružnici se na ni naváže)",
"Strecke: ersten Punkt wählen": "Úsečka: vyberte první bod",
