"<0>Erst ausklammern</0>{1}": "<0>Nejdřív vytknout</0>{1}",
"Beide Glieder enthalten {0}x. Man klammert es aus: {1}x({2}x + {3}).": "Oba členy obsahují {0}x. Vytkneme ho: {1}x({2}x + {3}).",
"Ein x², fünf x und sechs {0} werden zu einem Rechteck gelegt. Gesucht: zwei Zahlen mit Produkt {1} und Summe {2}.": "Jedno x², pět x a šest {0} se složí do obdélníku. Hledáme: dvě čísla se součinem {1} a součtem {2}.",
"Produkt −{0} und Summe −{1}: die Zahlen sind −{2} und {3}.": "Součin −{0} a součet −{1}: čísla jsou −{2} a {3}.",
"Aus x² − {0} wird (x + {1})(x − {2}): Der Streifen wird umgelegt.": "Z x² − {0} se stane (x + {1})(x − {2}): pruh se přeloží.",
"Quadrat, doppeltes Produkt, Quadrat: es ist ({0}x − {1}y)².": "Čtverec, dvojnásobek součinu, čtverec: je to ({0}x − {1}y)².",
"Zuerst den gemeinsamen Faktor {0}, dann die dritte binomische Formel: {1}(x + {2})(x − {3}).": "Nejdřív společný činitel {0}, potom třetí vzorec: {1}(x + {2})(x − {3}).",
