"Aus einer Urne mit n nummerierten Kugeln werden k Kugeln gezogen. Zwei Fragen legen das Modell fest: Wird zurückgelegt? Zählt die Reihenfolge?": "Z urny s n očíslovanými koulemi se tahá k koulí. Model určují dvě otázky: Vrací se koule? Záleží na pořadí?",
"Beobachte: Die vier Kombinationen ergeben vier Zählformeln. Mit «Neue Ziehung» siehst du ein Beispiel; die Rechnung zeigt die Anzahl der Möglichkeiten und die Wahrscheinlichkeit.": "Pozoruj: čtyři kombinace dávají čtyři počítací vzorce. Tlačítkem „Nový tah“ uvidíš příklad; výpočet ukazuje počet možností a pravděpodobnost.",
