"mit Zurücklegen": "s vracením",
"Beispiel:": "Příklad:",
"Ohne Zurücklegen kann man nicht mehr Kugeln ziehen, als in der Urne liegen (k ≤ n).": "Bez vracení nelze vytáhnout více koulí, než je v urně (k ≤ n).",
