"Der Punkt P liegt fest auf dem Graphen, der Punkt Q wandert. Die Sekante durch P und Q hat die Steigung ms = Δy / h.": "Bod P je pevný na grafu, bod Q se pohybuje. Sečna body P a Q má směrnici ms = Δy / h.",
"Ziehe Q (oder benutze den Regler) gegen P: Die Sekante wird zur Tangente, und ms nähert sich der Ableitung f′(x₀). Ziehe P, um die Stelle zu ändern.": "Přetáhni Q (nebo použij posuvník) k bodu P: sečna se mění v tečnu a ms se blíží derivaci f′(x₀). Přetažením P změníš místo.",
