"Differenzenquotient und Grenzwert": "Podíl diferencí a limita",
"Bei dieser Funktion lässt sich der Differenzenquotient nicht zu einem Term vereinfachen, der sich durch {0} kürzen lässt. Die Tabelle zeigt, wohin die Differenzenquotienten streben. Die Ableitung berechnest du mit den Ableitungsregeln.": "U této funkce nelze podíl diferencí zjednodušit na výraz, který by se dal zkrátit pomocí {0}. Tabulka ukazuje, k čemu se podíly diferencí blíží. Derivaci vypočítáš podle pravidel derivování.",
"Bei dieser Funktion lässt sich der Differenzenquotient nicht zu einem Term vereinfachen, der sich durch {0} kürzen lässt. Die Ableitungsfunktion findest du mit den Ableitungsregeln.": "U této funkce nelze podíl diferencí zjednodušit na výraz, který by se dal zkrátit pomocí {0}. Derivaci jako funkci najdeš podle pravidel derivování.",
