"Rechenweg: Integralfunktion": "Výpočet: integrální funkce",
"Die <0>Integralfunktion</0> sammelt die Fläche zwischen {1} und der {2}-Achse ab der festen Stelle {3}. Oberhalb der Achse wächst sie, unterhalb nimmt sie ab.": "<0>Integrální funkce</0> sbírá plochu mezi {1} a osou {2} od pevného bodu {3}. Nad osou roste, pod osou klesá.",
"<0>Schritt {1}:</0> Eine Stammfunktion {2} von {3} bestimmen.": "<0>Krok {1}:</0> Určit primitivní funkci {2} k {3}.",
"<0>Schritt {1}:</0> Hauptsatz der Differential- und Integralrechnung.": "<0>Krok {1}:</0> Základní věta integrálního počtu.",
"<0>Schritt {1}:</0> Ableiten der Integralfunktion gibt die Funktion zurück:": "<0>Krok {1}:</0> Derivováním integrální funkce dostaneme zpět funkci:",
"Die Steigung von {0} an der Stelle {1} ist {2}.": "Směrnice {0} v bodě {1} je {2}.",
"Für diese Funktion gibt es keine Stammfunktion in einfacher Form; die Integralfunktion wird numerisch berechnet.": "Tato funkce nemá primitivní funkci v jednoduchém tvaru; integrální funkce se počítá numericky.",
"Die Stammfunktion wird Schritt für Schritt mit den Integrationsregeln bestimmt. Danach folgt das bestimmte Integral zwischen a und b.": "Primitivní funkce se určuje krok za krokem pomocí pravidel integrování. Poté následuje určitý integrál mezi a a b.",
"Ziehe a und b auf der x-Achse. Die Stammfunktion ist nur bis auf eine Konstante C bestimmt: Alle Stammfunktionen sind gegeneinander verschoben.": "Přetáhni a a b po ose x. Primitivní funkce je určena jen až na konstantu C: všechny primitivní funkce jsou navzájem posunuté.",
"{0} <1>Fläche von a bis b färben</1>": "{0} <1>Vybarvit plochu od a do b</1>",
"{0} <1>Stammfunktion F einzeichnen</1>": "{0} <1>Zakreslit primitivní funkci F</1>",
"{0} <1>Schar F + C zeigen (andere Konstanten)</1>": "{0} <1>Zobrazit soustavu F + C (jiné konstanty)</1>",
