"Für diese Funktion gibt es keine Stammfunktion in einfacher Form (z. B. {0} oder {1}). Das bestimmte Integral wird numerisch berechnet.": "Tato funkce nemá primitivní funkci v jednoduchém tvaru (např. {0} nebo {1}). Určitý integrál se počítá numericky.",
"Für diese Funktion gibt es keine Stammfunktion in einfacher Form. Das Integral wird numerisch berechnet.": "Tato funkce nemá primitivní funkci v jednoduchém tvaru. Integrál se počítá numericky.",
