"<0>Schritt {1}:</0> Nullstellen von {2} im Intervall suchen ({3}).": "<0>Krok {1}:</0> Hledat nulové body {2} v intervalu ({3}).",
"Im Inneren des Intervalls gibt es keine Nullstelle, also wechselt das Vorzeichen nicht.": "Uvnitř intervalu není žádný nulový bod, takže se znaménko nemění.",
"<0>Schritt {1}:</0> Das Intervall an diesen Stellen teilen und jedes Stück einzeln integrieren. Unterhalb der Achse (bzw. von {2}) ist das Integral negativ, die Fläche ist sein Betrag.": "<0>Krok {1}:</0> Interval v těchto bodech rozdělit a každý kousek integrovat zvlášť. Pod osou (resp. pod {2}) je integrál záporný, plocha je jeho absolutní hodnota.",
