"<0>Schritt {1}:</0> Schnittstellen von {2} und {3} im Intervall suchen ({4}).": "<0>Krok {1}:</0> Hledat průsečíky {2} a {3} v intervalu ({4}).",
"Dreht man den Graphen von f um die x-Achse, entsteht ein Körper aus lauter dünnen Kreisscheiben. Jede Scheibe hat das Volumen π · {0}² · Δx.": "Otočíme-li graf f kolem osy x, vznikne těleso z mnoha tenkých kotoučů. Každý kotouč má objem π · {0}² · Δx.",
"Erhöhe die Zahl der Scheiben: Die Summe der Scheibenvolumen nähert sich dem Volumen V = π ∫ f².": "Zvyšuj počet kotoučů: součet objemů kotoučů se blíží objemu V = π ∫ f².",
