"Eine lineare Funktion {0} = m·x + q hat als Graph eine Gerade. Die Steigung m sagt, um wie viel y pro Schritt {1} nach rechts wächst (Steigungsdreieck), q ist der y-Achsenabschnitt.": "Lineární funkce {0} = m·x + q má za graf přímku. Směrnice m říká, o kolik y vzroste při každém kroku {1} doprava (směrnicový trojúhelník), q je úsek na ose y.",
"Ziehe den violetten Punkt S, um q zu ändern, oder verändere m mit dem Regler. Die Wertetabelle zeigt, dass y bei jedem Schritt um m wächst.": "Přetažením fialového bodu S změníš q, posuvníkem měníš m. Tabulka hodnot ukazuje, že y roste při každém kroku o m.",
"Steigung m und y-Achsenabschnitt q": "Směrnice m a úsek q na ose y",
