"Die Gerade verläuft parallel zur {0}-Achse und hat keine Nullstelle.": "Přímka je rovnoběžná s osou {0} a nemá nulový bod.",
"Die Steigung ist null: Die Gerade verläuft waagrecht.": "Směrnice je nula: přímka je vodorovná.",
"Die Gerade ist die {0}-Achse selbst: Jede Stelle ist eine Nullstelle.": "Přímka je sama osa {0}: každý bod je nulový bod.",
"Jede Stelle ist Nullstelle": "Každý bod je nulový bod",
"Das ist keine lineare Funktion. Erlaubt ist m·x + q.": "Toto není lineární funkce. Očekává se m·x + q.",
"Eine Gerade ist durch zwei Punkte oder durch einen Punkt und die Steigung festgelegt. Aus Δy und Δx folgt m, dann folgt q aus einem Punkt.": "Přímka je určena dvěma body nebo bodem a směrnicí. Z Δy a Δx vyplývá m, pak q určíme z jednoho bodu.",
"Ziehe die Punkte P und Q. Mit dem Punkt R kannst du die Parallele und die Senkrechte zur Geraden durch R zeigen.": "Přetáhni body P a Q. Pomocí bodu R můžeš zobrazit rovnoběžku a kolmici k přímce procházející bodem R.",
