"Ungerade Potenz: Die dritte Wurzel gibt es für jedes Vorzeichen, <0>genau eine Lösung</0>.": "Lichá mocnina: Třetí odmocnina existuje pro každé znaménko, <0>právě jedno řešení</0>.",
