"Beide Seiten mit dem Kehrwert des Exponenten potenzieren: {0}. Gerader Zähler: beide Vorzeichen.": "Obě strany umocnit na převrácenou hodnotu exponentu: {0}. Sudý čitatel: obě znaménka.",
