"<0>Lineare Funktionen</0><1>Steigung und y-Achsenabschnitt, Gerade aufstellen, Schnitt zweier Geraden, Tarife und Bewegung, Nullstelle, Senkrechte und Mittelsenkrechte</1>": "<0>Lineární funkce</0><1>Směrnice a úsek na ose y, sestavení přímky, průsečík dvou přímek, tarify a pohyb, nulový bod, kolmice a osa úsečky</1>",
"<0>Quadratische Funktionen</0><1>Parameter und drei Formen, Scheitelpunkt und quadratische Ergänzung, Nullstellen und Diskriminante, Parabel und Gerade, Parabel aus Punkten</1>": "<0>Kvadratické funkce</0><1>Parametry a tři tvary, vrchol a doplnění na čtverec, nulové body a diskriminant, parabola a přímka, parabola z bodů</1>",
"<0>Potenz- und Wurzelfunktionen</0><1>Potenzfunktionen x^n, negative Exponenten, Wurzelfunktionen als Umkehrung, allgemeine Form {2}^n + h, Potenz- und Wurzelgleichungen</1>": "<0>Mocninné a odmocninné funkce</0><1>Mocninné funkce x^n, záporné exponenty, odmocninné funkce jako inverze, obecný tvar {2}^n + h, mocninné a odmocninné rovnice</1>",
"Exponent n: {0} = {1}/xⁿ": "Exponent n: {0} = {1}/xⁿ",
