"<0>Entsprechende Seiten:</0> Jede Länge wird mit dem gleichen Faktor {1} multipliziert. Das Verhältnis Bild : Original ist für alle drei Seiten gleich:": "<0>Odpovídající si strany:</0> každá délka se násobí stejným koeficientem {1}. Poměr obraz : vzor je pro všechny tři strany stejný:",
