"Zwei Dreiecke (ABC und PQR) sind ähnlich, wenn sie in allen Winkeln übereinstimmen. Dann sind auch alle entsprechenden Seitenverhältnisse gleich. Gleiche Farben zeigen, welche Ecken und Seiten sich entsprechen.": "Dva trojúhelníky (ABC a PQR) jsou podobné, když se shodují ve všech úhlech. Pak jsou stejné i všechny poměry odpovídajících si stran. Stejné barvy ukazují, které vrcholy a strany si odpovídají.",
