"Beim zweiten Strahlensatz gehören zu den Parallelen immer die Abschnitte von {0} aus, nicht die Abschnitte {1} und {2}.": "U druhého pravidla patří k rovnoběžkám vždy úseky měřené od bodu {0}, nikoli úseky {1} a {2}.",
"<0>Fehlende Länge berechnen:</0> Gesucht ist {1}, bekannt sind {2}, {3} und {4}. Verhältnisgleichung aufstellen und nach {5} auflösen:": "<0>Výpočet chybějící délky:</0> hledáme {1}; známe {2}, {3} a {4}. Sestav úměru a vyjádři {5}:",
"<0>Zweiter Strahlensatz:</0> Die Parallelen stehen im gleichen Verhältnis wie die Abschnitte von {1} aus.": "<0>Druhé pravidlo (rovnoběžky):</0> rovnoběžné úsečky jsou ve stejném poměru jako úseky měřené od bodu {1}.",
"Ebenso die Abschnitte zwischen den Parallelen:": "Stejně tak úseky mezi rovnoběžkami:",
"<0>Erster Strahlensatz:</0> Die Abschnitte von {1} aus stehen auf beiden Strahlen im gleichen Verhältnis.": "<0>První pravidlo (úseky):</0> úseky měřené od bodu {1} jsou na obou polopřímkách ve stejném poměru.",
"<0>Ähnliche Dreiecke:</0> Weil {1}, stimmen {2} und {3} in allen Winkeln überein (gemeinsamer Winkel bei {4}, Stufenwinkel an Parallelen).": "<0>Podobné trojúhelníky:</0> protože {1}, shodují se {2} a {3} ve všech úhlech (společný úhel u {4}, souhlasné úhly u rovnoběžek).",
"Zwei Strahlen haben den gemeinsamen Anfangspunkt {0}. {1} und {2} liegen auf dem einen, {3} und {4} auf dem anderen Strahl (V-Figur).": "Dvě polopřímky mají společný počátek {0}. {1} a {2} leží na jedné, {3} a {4} na druhé polopřímce (útvar V).",
