"Werden zwei Strahlen mit Anfangspunkt Z von zwei Parallelen geschnitten, so sind die Dreiecke ZAB und ZCD ähnlich. Daraus folgen die Strahlensätze.": "Protnou-li dvě rovnoběžky dvě polopřímky s počátkem Z, jsou trojúhelníky ZAB a ZCD podobné. Z toho plynou pravidla o poměrech úseků.",
"Ziehe {0} und {1}: Zwei Parallelen schneiden die Strahlen aus Z, die Dreiecke ZAB und ZCD sind ähnlich – daraus folgen die Strahlensätze. Mit «D frei» siehst du, dass es ohne Parallelen nicht mehr stimmt.": "Táhni za {0} a {1}: dvě rovnoběžky protínají polopřímky vycházející ze Z, trojúhelníky ZAB a ZCD jsou podobné – z toho plynou pravidla o poměrech úseků. S volbou „D volně“ uvidíš, že bez rovnoběžek už to neplatí.",
"Vorgehen: gleiche Winkel markieren, ähnliche Dreiecke mit entsprechenden Ecken in derselben Reihenfolge notieren, Verhältnisgleichung aufstellen und lösen.": "Postup: vyznač shodné úhly, zapiš podobné trojúhelníky s odpovídajícími si vrcholy ve stejném pořadí, sestav úměru a vyřeš ji.",
