"<0>Drei Dreiecke in einem:</0> Die Höhe {1} teilt das rechtwinklige Dreieck {2} in zwei Teildreiecke. Alle drei haben die Winkel {3}, {4} und {5}, also gilt": "<0>Tři trojúhelníky v jednom:</0> výška {1} dělí pravoúhlý trojúhelník {2} na dva menší trojúhelníky. Všechny tři mají úhly {3}, {4} a {5}, takže platí",
