"Die Höhe CD teilt das rechtwinklige Dreieck ABC in zwei Teildreiecke. Alle drei Dreiecke haben die Winkel α, β und {0}° und sind deshalb ähnlich: ΔADC ∼ ΔCDB ∼ ΔACB.": "Výška CD dělí pravoúhlý trojúhelník ABC na dva menší trojúhelníky. Všechny tři trojúhelníky mají úhly α, β a {0}°, a jsou proto podobné: ΔADC ∼ ΔCDB ∼ ΔACB.",
"Ziehe {0} auf dem Thaleskreis oder die Ecken {1} und {2}: Die Höhe CD teilt das rechtwinklige Dreieck in zwei Teildreiecke, alle drei sind ähnlich (Winkel α, β, {3}°). Rechts stehen sie in gleicher Lage nebeneinander.": "Táhni za {0} po Thaletově kružnici nebo za vrcholy {1} a {2}: výška CD dělí pravoúhlý trojúhelník na dva menší trojúhelníky a všechny tři jsou podobné (úhly α, β, {3}°). Vpravo stojí vedle sebe ve stejné poloze.",
"Winkel und Seitenlängen lassen sich links einblenden; rechts stehen die Seitenverhältnisse als Brüche.": "Úhly a délky stran lze zobrazit vlevo; vpravo jsou poměry stran zapsané jako zlomky.",
"«Abbildung vorführen …» spielt einzelne Abbildungen ab; «⟲ Bild auf das Original legen» stellt den Anfang wieder her.": "„Předvést zobrazení …“ přehraje jednotlivá zobrazení; „⟲ Položit obraz na vzor“ obnoví výchozí stav.",
"«Mehrere nacheinander» verknüpft die Abbildungen in fester Reihenfolge: spiegeln, um O drehen, von Z aus strecken, verschieben.": "„Několik po sobě“ skládá zobrazení v pevném pořadí: souměrnost, otočení kolem O, stejnolehlost se středem Z, posunutí.",
"Das Original ABC bleibt fest. Unter «Abbildung» wählst du genau eine Grundabbildung: Verschiebung, Drehung um den Ursprung, Spiegelung an der x- oder y-Achse oder zentrische Streckung von Z aus. Das Bild A′B′C′ zeigt dann nur diese eine Abbildung; du kannst es auch mit der Maus verschieben, drehen bzw. strecken.": "Vzor ABC zůstává na místě. V poli „Zobrazení“ zvolíš právě jedno základní zobrazení: posunutí, otočení kolem počátku, osovou souměrnost podle osy x nebo y, nebo stejnolehlost se středem Z. Obraz A′B′C′ pak ukazuje jen toto jedno zobrazení; můžeš ho také myší posouvat, otáčet nebo zvětšovat.",
