"<0>Zusammenhang:</0> Jeder Punkt wandert um dieselbe Strecke in dieselbe Richtung: {1}. Die Strecken {2} sind parallel und gleich lang.": "<0>Souvislost:</0> každý bod se posune o stejnou vzdálenost stejným směrem: {1}. Úsečky {2} jsou rovnoběžné a stejně dlouhé.",
