"<0>Zusammenhang:</0> Punkt und Bildpunkt liegen gleich weit von der Achse entfernt, ihre Verbindung steht senkrecht auf der Achse: {1}. Der Umlaufsinn kehrt sich um.": "<0>Souvislost:</0> bod a jeho obraz jsou stejně daleko od osy a jejich spojnice je k ose kolmá: {1}. Smysl oběhu se obrátí.",
