"Reihenfolge: zuerst spiegeln, dann um O drehen, dann von Z aus strecken, zuletzt verschieben. Jetzt: Drehung, dann zentrische Streckung.": "Pořadí: nejprve souměrnost, pak otočení kolem O, potom stejnolehlost se středem Z, nakonec posunutí. Teď: otočení, pak stejnolehlost.",
