"Darum sind auch die Seitenverhältnisse <0>nicht</0> alle gleich:": "Proto ani poměry stran <0>nejsou</0> všechny stejné:",
"<0>Winkel vergleichen:</0> Auch bei der besten Zuordnung ({1}) unterscheiden sich die Winkel um bis zu {2}.": "<0>Porovnání úhlů:</0> i při nejlepším přiřazení ({1}) se úhly liší až o {2}.",
"<0>Ähnliche Dreiecke:</0> Weil {1}, stimmen {2} und {3} in allen Winkeln überein (Scheitelwinkel bei {4}, Wechselwinkel an Parallelen).": "<0>Podobné trojúhelníky:</0> protože {1}, shodují se {2} a {3} ve všech úhlech (vrcholové úhly u {4}, střídavé úhly u rovnoběžek).",
"Zwei Geraden schneiden sich in {0}. {1} und {2} liegen auf der einen, {3} und {4} auf der anderen Geraden, auf verschiedenen Seiten von {5} (X-Figur).": "Dvě přímky se protínají v bodě {0}. {1} a {2} leží na jedné, {3} a {4} na druhé přímce, na opačných stranách od {5} (útvar X).",
"Die Verhältnisse sind verschieden, weil {0}": "Poměry se liší, protože {0}",
"<0>Achtung:</0> {1} und {2} sind <3>nicht</3> parallel. Die Dreiecke {4} und {5} sind dann nicht ähnlich, die Strahlensätze gelten nicht:": "<0>Pozor:</0> {1} a {2} <3>nejsou</3> rovnoběžné. Trojúhelníky {4} a {5} pak nejsou podobné a pravidla o poměrech úseků neplatí:",
"nicht parallel": "nejsou rovnoběžné",
"Ziehe D, bis CD parallel zu AB ist.": "Táhni za D, dokud nebude CD rovnoběžná s AB.",
"Nicht parallel: Die Strahlensätze gelten nicht.": "Nerovnoběžné: pravidla o poměrech úseků neplatí.",
"∥ D auf die Parallele setzen": "∥ Umístit D na rovnoběžku",
"{0}Ähnlichkeit{1}": "{0}Podobnost{1}",
"Das Dreieck ABC bleibt fest. Sein Bild A′B′C′ entsteht durch Verschieben, Drehen um den Ursprung O, Spiegeln an der x- oder y-Achse und zentrisches Strecken von Z aus. Die ersten drei Abbildungen erhalten alle Längen (Bild und Original sind kongruent), die Streckung multipliziert jede Länge mit |k|. Die Winkel bleiben immer gleich.": "Trojúhelník ABC zůstává na místě. Jeho obraz A′B′C′ vznikne posunutím, otočením kolem počátku O, osovou souměrností podle osy x nebo y a stejnolehlostí se středem Z. První tři zobrazení zachovávají všechny délky (obraz a vzor jsou shodné); stejnolehlost násobí každou délku číslem |k|. Úhly zůstávají vždy stejné.",
