"Zwischen f und der x-Achse liegen von a bis b n gleich breite Rechtecke. Die Untersumme (grün) nimmt den kleinsten, die Obersumme (blau) den grössten Funktionswert jedes Streifens.": "Mezi f a osou x leží od a do b n stejně širokých obdélníků. Dolní součet (zelený) bere nejmenší, horní součet (modrý) největší funkční hodnotu v každém pruhu.",
"Eine lineare Funktion {0} = m·x + q hat als Graph eine Gerade. Die Steigung m sagt, um wie viel y pro Schritt {1} nach rechts wächst, q ist der y-Achsenabschnitt.": "Grafem lineární funkce {0} = m·x + q je přímka. Směrnice m říká, o kolik vzroste y při každém kroku o {1} doprava, q je úsek na ose y.",
