"Eine Folge ist eine durchnummerierte Liste von Zahlen a₁, a₂, a₃, … Explizit berechnet man jedes Glied direkt aus n, rekursiv aus dem Vorgänger. Die Glieder erscheinen als Punkte (n | aₙ).": "Posloupnost je očíslovaný seznam čísel a₁, a₂, a₃, … Vzorcem pro n-tý člen se každý člen počítá přímo z n, rekurentně z předchozího členu. Členy se zobrazují jako body (n | aₙ).",
