"Blickrichtung": "Směr pohledu",
"Eine Ebene im Raum hat die Koordinatenform a·x + b·y + c·z = d. Der Normalenvektor (a | b | c) steht senkrecht auf ihr. Achsenabschnitte: zwei Koordinaten null setzen. Buchstaben in der Gleichung werden zu Schiebern.": "Rovina v prostoru má obecný tvar a·x + b·y + c·z = d. Normálový vektor (a | b | c) je k ní kolmý. Průsečíky s osami: dvě souřadnice polož rovny nule. Písmena v rovnici se změní v posuvníky.",
