"Lagemasse: Mittelwert (Summe durch Anzahl), Median (Wert in der Mitte der geordneten Liste), Modus (häufigster Wert). Streumasse: Spannweite, Quartilsabstand Q₃ − Q₁ und Standardabweichung. Diagramme: Punkt-, Säulen-, Kreisdiagramm, Histogramm (Klassen) und Boxplot.": "Míry polohy: průměr (součet dělený počtem), medián (hodnota uprostřed uspořádaného seznamu), modus (nejčastější hodnota). Míry rozptýlení: rozpětí, mezikvartilové rozpětí Q₃ − Q₁ a směrodatná odchylka. Diagramy: bodový, sloupcový, kruhový, histogram (třídy) a krabicový graf.",
"{0}Statistik und Stochastik rechnen{1}": "{0}Statistika a pravděpodobnost: výpočty{1}",
"{0} Rechenweg als Karte anzeigen": "{0} Zobrazit postup na kartě",
