"Ziehe die {0} oder tippe links eine Liste ein: {1} und {2} wandern mit, der {3} zeigt die {4}. Wie stark zieht ein Ausreisser den Mittelwert, wie wenig den Median?": "Táhni za {0} nebo vlevo zapiš seznam: {1} a {2} se posouvají s nimi, {3} ukazuje {4}. Jak silně táhne odlehlá hodnota průměr a jak málo medián?",
