"<0>Quartile:</0> Der Median teilt die Liste in eine untere und eine obere Hälfte (der Median selbst gehört zu keiner Hälfte). {1} ist der Median der unteren, {2} der Median der oberen Hälfte.": "<0>Kvartily:</0> medián dělí seznam na dolní a horní polovinu (samotný medián nepatří do žádné poloviny). {1} je medián dolní poloviny, {2} medián horní poloviny.",
"<0>Median</0> (Zentralwert): Bei ungerader Anzahl ist es der mittlere Wert, hier der {1}. Wert.": "<0>Medián</0> (prostřední hodnota): při lichém počtu je to prostřední hodnota, zde {1}. hodnota.",
