"Ein Hypothesentest prüft eine Annahme H₀ über eine Wahrscheinlichkeit p. Unter H₀ ist die Trefferzahl binomialverteilt. Der Ablehnungsbereich enthält die Werte, die unter H₀ zusammen höchstens die Wahrscheinlichkeit α (Signifikanzniveau) haben. Fehler {0}. Art: H₀ wird verworfen, obwohl sie stimmt.": "Test hypotézy ověřuje předpoklad H₀ o pravděpodobnosti p. Za platnosti H₀ má počet úspěchů binomické rozdělení. Kritický obor obsahuje hodnoty, které mají za platnosti H₀ dohromady nejvýše pravděpodobnost α (hladina významnosti). Chyba {0}. druhu: H₀ se zamítne, ačkoli platí.",
"Poissonverteilung: Grenzfall der Binomialverteilung für n → ∞ und p → {0} bei festem Mittelwert λ = n·p. Normalverteilung: Für grosses n rücken die Säulen der Binomialverteilung, in Einheiten von σ gemessen, immer dichter zusammen und bilden die Glockenkurve; die Zufallsgrösse wird stetig (Satz von de Moivre und Laplace).": "Poissonovo rozdělení: limitní případ binomického rozdělení pro n → ∞ a p → {0} při pevné střední hodnotě λ = n·p. Normální rozdělení: pro velké n se sloupce binomického rozdělení, měřené v jednotkách σ, stále více přibližují a vytvářejí zvonovou křivku; náhodná veličina se stává spojitou (Moivreova-Laplaceova věta).",
"Viele Messgrössen (Körpergrösse, Messfehler, Abfüllmengen) sind annähernd normalverteilt. Wahrscheinlichkeiten sind Flächen unter der Glockenkurve; sie hängen nur davon ab, wie viele Standardabweichungen σ die Grenze vom Mittelwert μ entfernt ist: z = (x − μ)/σ. Beidseitig: μ ± {0}σ enthält {1} %, μ ± {2}σ {3} %, μ ± {4}σ {5} %. Umgekehrt gehören zu {6} %, {7} % und {8} % die Grenzen {9}σ, {10}σ und {11}σ.": "Mnoho měřených veličin (tělesná výška, chyby měření, plnicí množství) má přibližně normální rozdělení. Pravděpodobnosti jsou obsahy pod zvonovou křivkou; závisejí jen na tom, kolik směrodatných odchylek σ je mez vzdálena od střední hodnoty μ: z = (x − μ)/σ. Oboustranně: μ ± {0}σ obsahuje {1} %, μ ± {2}σ {3} %, μ ± {4}σ {5} %. Obráceně patří k {6} %, {7} % a {8} % meze {9}σ, {10}σ a {11}σ.",
"Eine Zufallsgrösse ordnet jedem Ergebnis eine Zahl zu (z. B. eine Auszahlung). Erwartungswert {0} = Σ xᵢ·{1}: der Mittelwert auf lange Sicht. Ein Spiel ist fair, wenn der Einsatz gleich dem Erwartungswert der Auszahlung ist.": "Náhodná veličina přiřazuje každému výsledku číslo (např. výplatu). Střední hodnota {0} = Σ xᵢ·{1}: průměr v dlouhodobém měřítku. Hra je spravedlivá, když se vklad rovná střední hodnotě výplaty.",
"Die Poissonverteilung zählt, wie oft ein Ereignis in einem festen Zeitraum (oder auf einer Seite, Strecke, Fläche) eintritt, wenn die Ereignisse unabhängig und im Mittel gleich häufig auftreten: {0} = λᵏ/k! · e^(−λ). Dabei ist λ die mittlere Anzahl; Erwartungswert und Varianz sind beide λ. Für grosses n und kleines p nähert sie die Binomialverteilung mit λ = n·p an.": "Poissonovo rozdělení počítá, kolikrát jev nastane v pevném časovém úseku (nebo na stránce, úseku, ploše), když jevy nastávají nezávisle a v průměru stejně často: {0} = λᵏ/k! · e^(−λ). Přitom λ je průměrný počet; střední hodnota i rozptyl jsou rovny λ. Pro velké n a malé p aproximuje binomické rozdělení s λ = n·p.",
"Eine Bernoulli-Kette ist ein Versuch mit Treffer (p) und Niete, n-mal unabhängig wiederholt. Die Trefferzahl X ist binomialverteilt: {0} = (n über k)·pᵏ·({1} − p)ⁿ⁻ᵏ. Erwartungswert μ = n·p, Standardabweichung σ = √(n·p·({2} − p)).": "Bernoulliho schéma je pokus s úspěchem (p) a neúspěchem, n-krát nezávisle opakovaný. Počet úspěchů X má binomické rozdělení: {0} = (n nad k)·pᵏ·({1} − p)ⁿ⁻ᵏ. Střední hodnota μ = n·p, směrodatná odchylka σ = √(n·p·({2} − p)).",
"Mehrstufige Zufallsexperimente zeichnet man als Baumdiagramm. {0}. Pfadregel: Wahrscheinlichkeiten entlang eines Pfades multiplizieren. {1}. Pfadregel: Wahrscheinlichkeiten aller Pfade eines Ereignisses addieren. Ohne Zurücklegen ändern sich die Wahrscheinlichkeiten von Stufe zu Stufe.": "Vícestupňové náhodné pokusy se kreslí jako stromový diagram. {0}. pravidlo: pravděpodobnosti podél větve se násobí. {1}. pravidlo: pravděpodobnosti všech větví jevu se sčítají. Bez vracení se pravděpodobnosti mění od stupně ke stupni.",
"Jede Ansicht hat Beispiele; der Rechenweg rechts zeigt Formel und Zwischenschritte mit deinen Zahlen.": "Každé zobrazení má příklady; postup vpravo ukazuje vzorec a mezikroky s tvými čísly.",
"Normalverteilung: Grenze ziehen oder die Grenze x, die Anzahl σ bzw. die Prozentzahl eintippen – die anderen beiden rechnen mit. «Art» schaltet zwischen linksseitig, rechtsseitig, zwischen zwei Grenzen und beidseitig um. Die Knöpfe {0}σ, {1}σ, {2}σ und {3} %, {4} %, {5} % setzen die Merkzahlen.": "Normální rozdělení: táhni za mez nebo zapiš mez x, počet σ či procento – ostatní dvě hodnoty se dopočítají. „Druh“ přepíná mezi levostranně, pravostranně, mezi dvěma mezemi a oboustranně. Tlačítka {0}σ, {1}σ, {2}σ a {3} %, {4} %, {5} % nastaví hodnoty, které stojí za zapamatování.",
"«Grenzwerte»: Mit dem Regler oder «{0} n wachsen lassen» geht die Binomialverteilung in die Poisson- bzw. Normalverteilung über; der Rechenweg enthält die Herleitung der Formel mit den aktuellen Zahlen.": "„Limity“: posuvníkem nebo tlačítkem „{0} Nechat n růst“ přejde binomické rozdělení v Poissonovo, případně normální; postup obsahuje odvození vzorce s aktuálními čísly.",
"Datenanalyse: Eigene Werte tippst du links als Liste ein.": "Analýza dat: vlastní hodnoty zapíšeš vlevo jako seznam.",
"Zahlen links ändern oder Punkte, Grenzen und Balken im Bild ziehen – beides gehört zusammen.": "Měň čísla vlevo nebo táhni za body, meze a sloupce v obrázku – obojí patří k sobě.",
