"Formel:": "Vzorec:",
"Die Poissonverteilung beschreibt, <0>wie oft ein Ereignis</0> in einem festen Zeitraum (oder auf einer Seite, einer Strecke, einer Fläche) eintritt, wenn die Ereignisse einzeln, unabhängig voneinander und im Mittel gleich häufig auftreten. {1} zählt die Ereignisse, {2} ist ihre <3>mittlere Anzahl</3>.": "Poissonovo rozdělení popisuje, <0>kolikrát jev</0> nastane v pevném časovém úseku (nebo na stránce, úseku, ploše), když jevy nastávají jednotlivě, nezávisle na sobě a v průměru stejně často. {1} počítá jevy, {2} je jejich <3>průměrný počet</3>.",
