"Ziehe die {0} an {1} oder am {2} nach oben und unten: Die Diskriminante D entscheidet, ob es zwei, eine oder keine {3} gibt. «{4} Parabel durch die x-Achse schieben» zeigt den Übergang von zwei über eine zu keiner Nullstelle: Nahe der x-Achse wird sie langsamer und hält bei D = {5} an, bis du «{6} weiter» drückst. Wähle das Lösungsverfahren für den Rechenweg.": "Táhni křivku ({0}) nahoru a dolů za {1} nebo za {2}: diskriminant D rozhoduje, zda existují dva, jeden, nebo žádný ({3}). „{4} Posunout parabolu přes osu x“ ukáže přechod od dvou nulových bodů přes jeden k žádnému: blízko osy x pohyb zpomalí a při D = {5} se zastaví, dokud nestiskneš „{6} dále“. Zvol metodu řešení pro postup.",
