"<0>Wertetabelle:</0> Man wählt Stellen {1} (hier ab {2} im Abstand {3}) und setzt jede in die Vorschrift ein. Das Einsetzen Schritt für Schritt:": "<0>Tabulka hodnot:</0> zvolíme hodnoty {1} (zde od {2} s krokem {3}) a každou dosadíme do předpisu. Dosazování krok za krokem:",
"<0>Funktion = eindeutige Zuordnung:</0> Eine Funktion {1} ordnet <2>jeder</2> Zahl {3} aus dem Definitionsbereich <4>genau eine</4> Zahl {5} zu. Die Rechenvorschrift sagt, wie aus {6} der Wert {7} entsteht.": "<0>Funkce = jednoznačné přiřazení:</0> funkce {1} přiřazuje <2>každému</2> číslu {3} z definičního oboru <4>právě jedno</4> číslo {5}. Předpis říká, jak z {6} vznikne hodnota {7}.",
