"Ziehe den {0} auf dem {1}: Sein Spiegelpunkt {2} an der {3} liegt auf dem {4}. Die Umkehrfunktion vertauscht x und y; «{5} Graph an y = x umklappen» zeigt die Spiegelung als Bewegung.": "Táhni za {0} po {1}: jeho souměrný bod {2} podle {3} leží na {4}. Inverzní funkce zaměňuje x a y; „{5} Překlopit graf podle y = x“ ukáže souměrnost jako pohyb.",
