"Ziehe die {0} auf und ab und zähle ihre Schnittpunkte mit dem {1}: Ist es nie mehr als einer, ist f umkehrbar. Sonst schränkt man den Definitionsbereich ein (rote Grenze r).": "Táhni za {0} nahoru a dolů a počítej body, ve kterých ji protíná {1}: není-li jich nikdy víc než jeden, má f inverzní funkci. Jinak se omezí definiční obor (červená mez r).",
"Wähle eine Funktion: Rechts wird y = {0} nach x aufgelöst, dann werden x und y vertauscht. Zur Probe ziehe {1} auf {2}: Der Spiegelpunkt {3} liegt auf {4}.": "Zvol funkci: vpravo se z rovnice y = {0} vyjádří x, pak se x a y zamění. Na zkoušku táhni za {1} po {2}: souměrný bod {3} leží na {4}.",
"Wähle ein Paar und ziehe den {0} auf {1}: Sein Spiegelpunkt {2} liegt auf {3} – erst f, dann f⁻¹ führt zum Ausgangswert zurück. Beachte die eingeschränkten Bereiche bei x², sin, cos und tan.": "Zvol dvojici a táhni za {0} po {1}: jeho souměrný bod {2} leží na {3} – nejprve f, potom f⁻¹ vede zpět k výchozí hodnotě. Všimni si omezených oborů u x², sin, cos a tan.",
"Die Winkelhalbierende y = x und die Umkehrfunktion f⁻¹ lassen sich links ein- und ausblenden.": "Přímku y = x a inverzní funkci f⁻¹ lze vlevo zobrazit nebo skrýt.",
"Bei «Umkehrbarkeit» ziehst du die waagrechte Gerade y = k und die rote Grenze r, die den Definitionsbereich einschränkt.": "V zobrazení „Prostost a zúžení definičního oboru“ táhneš za vodorovnou přímku y = k a za červenou mez r, která omezuje definiční obor.",
"Die Funktion wählst du über «Beispiel wählen …» oder tippst sie ein (lineare Funktionen, Potenz-, Exponential- und Logarithmusfunktionen).": "Funkci zvolíš přes „Vyberte příklad …“ nebo ji zapíšeš (lineární, mocninné, exponenciální a logaritmické funkce).",
