"<0>Bereiche tauschen:</0> Was bei {1} herauskommt (Wertebereich), darf bei {2} hinein (Definitionsbereich), und umgekehrt.": "<0>Záměna oborů:</0> co z {1} vychází (obor hodnot), smí do {2} vstoupit (definiční obor), a naopak.",
"<0>Graph:</0> Jeder Punkt {1} auf dem Graphen von {2} wird zum Punkt {3} auf dem Graphen von {4}. Koordinaten tauschen heisst <5>Spiegeln an der Winkelhalbierenden</5> {6}.": "<0>Graf:</0> každý bod {1} grafu {2} se stane bodem {3} grafu {4}. Záměna souřadnic znamená <5>souměrnost podle přímky</5> {6}.",
"<0>Zuordnung rückwärts lesen:</0> {1} ordnet jedem {2} einen Wert {3} zu. Die <4>Umkehrfunktion</4> {5} macht das rückgängig: Sie ordnet jedem Wert {6} das ursprüngliche {7} zu. In der Wertetabelle werden dazu einfach die beiden Zeilen vertauscht.": "<0>Čtení přiřazení pozpátku:</0> {1} přiřazuje každému {2} hodnotu {3}. <4>Inverzní funkce</4> {5} to vrací zpět: každé hodnotě {6} přiřadí původní {7}. V tabulce hodnot se k tomu jen zamění oba řádky.",
