"{0} ist auf {1} umkehrbar (streng monoton wachsend)": "{0} má na {1} inverzní funkci (ryze rostoucí)",
"<0>Hier:</0> {1} ist auf dem ganzen Definitionsbereich streng monoton wachsend. Jede waagrechte Gerade trifft den Graphen höchstens einmal, also ist {2} <3>umkehrbar</3>.": "<0>Zde:</0> {1} je na celém definičním oboru ryze rostoucí. Každá vodorovná přímka protne graf nejvýše jednou, takže {2} <3>má inverzní funkci</3>.",
"<0>Kriterium:</0> Eine Funktion ist umkehrbar, wenn jeder Wert {1} <2>höchstens einmal</2> angenommen wird. Im Bild: Jede <3>waagrechte Gerade</3> {4} schneidet den Graphen höchstens einmal. Das ist sicher erfüllt, wenn {5} streng monoton ist.": "<0>Kritérium:</0> funkce má inverzní funkci, když každé hodnoty {1} nabývá <2>nejvýše jednou</2>. V obrázku: každá <3>vodorovná přímka</3> {4} protne graf nejvýše jednou. To je jistě splněno, je-li {5} ryze monotónní.",
"Rechenweg: Umkehrbarkeit": "Postup: Prostost",
"f ist streng monoton: jede waagrechte Gerade trifft höchstens einmal": "f je ryze monotónní: každá vodorovná přímka ji protne nejvýše jednou",
