"Erkannt: Potenz-/Wurzelfunktion – streng monoton, umkehrbar.": "Rozpoznáno: mocninná/odmocninová funkce – ryze monotónní, má inverzní funkci.",
"Umkehrbar ist eine Funktion nur, wenn jeder Wert höchstens einmal vorkommt: Jede waagrechte Gerade darf den Graphen höchstens einmal schneiden. Streng monotone Funktionen erfüllen das. Sonst hilft eine Einschränkung des Definitionsbereichs.": "Inverzní funkci má funkce jen tehdy, když se každá hodnota vyskytuje nejvýše jednou: každá vodorovná přímka smí graf protnout nejvýše jednou. Ryze monotónní funkce to splňují. Jinak pomůže omezení definičního oboru.",
