"<0>Schritt {1}:</0> Funktionsgleichung mit {2} schreiben.": "<0>Krok {1}:</0> zapsat předpis funkce s {2}.",
"Rechenweg: Umkehrfunktion berechnen": "Postup: Výpočet inverzní funkce",
"Die Umkehrfunktion berechnet man in drei Schritten: y = {0} nach x auflösen (Rechenschritte rückgängig machen), dann x und y vertauschen, dann Definitions- und Wertebereich tauschen.": "Inverzní funkce se počítá ve třech krocích: z y = {0} vyjádřit x (vrátit početní kroky zpět), pak zaměnit x a y, nakonec zaměnit definiční obor a obor hodnot.",
"{0} und {1} sind Umkehrfunktionen voneinander": "{0} a {1} jsou navzájem inverzní funkce",
