"Eine Zunahme um p % bedeutet Multiplikation mit q = {0} + p/{1}, eine Abnahme mit q = {2} − p/{3}. Bei mehreren Veränderungen nacheinander werden die Faktoren multipliziert, nicht die Prozente addiert. Den Grundwert findet man, indem man den neuen Wert durch den Faktor teilt.": "Nárůst o p % znamená násobení číslem q = {0} + p/{1}, pokles číslem q = {2} − p/{3}. Při několika změnách po sobě se násobí faktory, procenta se nesčítají. Základ najdeme tak, že novou hodnotu vydělíme faktorem.",
