"Bei «Exponentialgleichungen» wählst du links eine Anwendung (Zinseszins, Zerfall, Abkühlung …) oder eine freie Gleichung; die Gerade y = c lässt sich ziehen.": "V zobrazení „Exponenciální rovnice“ zvolíš vlevo aplikaci (složené úročení, rozpad, chladnutí …) nebo volnou rovnici; za přímku y = c lze táhnout.",
