"<0>Vergleich:</0> Lineares Wachstum <1>addiert</1> pro Schritt immer dieselbe Zahl, exponentielles Wachstum <2>multipliziert</2> immer mit demselben Faktor. Darum überholt jede wachsende Exponentialfunktion irgendwann jede Gerade.": "<0>Srovnání:</0> lineární růst v každém kroku <1>přičítá</1> stále stejné číslo, exponenciální růst <2>násobí</2> stále stejným faktorem. Proto každá rostoucí exponenciální funkce jednou předstihne každou přímku.",
