"{0} Ziehe die Punkte im Bild oder die orange Gerade. Oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Táhni za body v obrázku nebo za oranžovou přímku. Vlevo nahoře volíš zobrazení, vpravo je postup.",
"{0} ist die Basis, bei der Funktionswert und Steigung überall übereinstimmen": "{0} je základ, při kterém se funkční hodnota a směrnice všude shodují",
"Jede Exponentialfunktion lässt sich mit der Basis {0} schreiben: {1}. Darum rechnet man in der Analysis fast nur mit {2} und {3}.": "Každou exponenciální funkci lze zapsat se základem {0}: {1}. Proto se v analýze počítá skoro jen s {2} a {3}.",
"<0>Andere Basen:</0> Bei {1} ist die Steigung im Punkt {2} nur {3}, bei {4} schon {5}. Genau bei der Basis {6} ist sie {7}. Allgemein gilt:": "<0>Jiné základy:</0> u {1} je směrnice v bodě {2} jen {3}, u {4} už {5}. Právě při základu {6} je {7}. Obecně platí:",
"<0>Tangente an der Stelle</0> {1}: Steigung {2}, Berührpunkt {3}.": "<0>Tečna v místě</0> {1}: směrnice {2}, bod dotyku {3}.",
"<0>Die Besonderheit von</0> {1}: Die Steigung der Tangente ist an jeder Stelle gleich dem Funktionswert. Die Funktion ist ihre eigene Ableitung.": "<0>Zvláštnost funkce</0> {1}: směrnice tečny je v každém místě rovna funkční hodnotě. Funkce je svou vlastní derivací.",
"<0>Woher kommt e?</0> Ein Kapital wächst um {1} pro Jahr. Wird der Zins in {2} Teilschritten gutgeschrieben, wächst es mit dem Faktor {3}. Je feiner die Schritte, desto näher kommt der Faktor einer festen Zahl:": "<0>Odkud se bere e?</0> Kapitál roste o {1} ročně. Připisuje-li se úrok v {2} dílčích krocích, roste s faktorem {3}. Čím jemnější kroky, tím víc se faktor blíží pevnému číslu:",
