"<0>Logarithmengesetze</0> (aus den Potenzgesetzen): Ein Produkt wird zur Summe, ein Quotient zur Differenz, eine Potenz zum Vielfachen.": "<0>Pravidla pro logaritmy</0> (z pravidel pro mocniny): součin přejde v součet, podíl v rozdíl, mocnina v násobek.",
"<0>Besondere Werte:</0> {1} und {2}, also:": "<0>Zvláštní hodnoty:</0> {1} a {2}, tedy:",
"<0>Definitions- und Wertebereich tauschen:</0> {1} nimmt nur positive Werte an ({2}), also ist {3} nur für positive Zahlen definiert. Die {4}-Achse ist senkrechte Asymptote von {5}.": "<0>Definiční obor a obor hodnot se zamění:</0> {1} nabývá jen kladných hodnot ({2}), takže {3} je definován jen pro kladná čísla. Osa {4} je svislou asymptotou funkce {5}.",
"<0>Spiegelung:</0> Der Graph von {1} ist das Spiegelbild des Graphen von {2} an der Winkelhalbierenden {3}: Aus {4} wird {5}.": "<0>Souměrnost:</0> graf {1} je obrazem grafu {2} v souměrnosti podle přímky {3}: z {4} se stane {5}.",
"<0>Die Frage umdrehen:</0> Bei {1} fragt man: Welcher Wert gehört zu {2}? Die Umkehrung fragt: <3>Mit welchem Exponenten</3> muss ich {4} potenzieren, um {5} zu erhalten? Dieser Exponent heisst <6>Logarithmus</6> von {7} zur Basis {8}.": "<0>Obrátit otázku:</0> u {1} se ptáme: jaká hodnota patří k {2}? Inverze se ptá: <3>na jaký exponent</3> musím umocnit {4}, abych dostal {5}? Tento exponent se nazývá <6>logaritmus</6> čísla {7} o základu {8}.",
