"Ziehe den {0} auf dem Einheitskreis oder lass den Winkel drehen: Die Höhe sin φ zeichnet rechts die {1}, der waagrechte Abstand cos φ die {2}. Besondere Winkel wie {3}°, {4}° und {5}° liefern exakte Werte.": "Posouvej {0} po jednotkové kružnici nebo nech úhel otáčet: z výšky sin φ vzniká vpravo {1}, z vodorovné vzdálenosti cos φ {2}. Významné úhly jako {3}°, {4}° a {5}° dávají přesné hodnoty.",
