"Ziehe den {0} auf dem Kreis: Der Tangens ist die Steigung des Strahls durch P, abzulesen an der senkrechten Tangente bei x = {1}. Rechts entsteht der {2}; nahe {3}° wächst er über alle Grenzen (Polstelle).": "Posouvej {0} po kružnici: tangens je směrnice polopřímky procházející bodem P, odečte se na svislé tečně u x = {1}. Vpravo vzniká {2}; v blízkosti {3}° roste nade všechny meze (pól).",
