"Im rechtwinkligen Dreieck gilt bezogen auf einen spitzen Winkel α: sin α = Gegenkathete : Hypotenuse, cos α = Ankathete : Hypotenuse, tan α = Gegenkathete : Ankathete. Mit zwei bekannten Stücken (darunter eine Seite) berechnet man alle anderen; dazu kommen Pythagoras und α + β = {0}°.": "V pravoúhlém trojúhelníku platí vzhledem k ostrému úhlu α: sin α = protilehlá odvěsna : přepona, cos α = přilehlá odvěsna : přepona, tan α = protilehlá odvěsna : přilehlá odvěsna. Ze dvou známých prvků (z nichž jeden je strana) se vypočítají všechny ostatní; k tomu se přidává Pythagorova věta a α + β = {0}°.",
"Ankathete": "Přilehlá odvěsna",
