"Ziehe die Ecken {0} und {1}: Für den Winkel {2} ist a die {3}, b die {4} und c die {5}. sin α, cos α und tan α sind ihre Verhältnisse – sie hängen nur vom Winkel ab, nicht von der Grösse des Dreiecks. Wähle oben, was gegeben ist.": "Posouvej vrcholy {0} a {1}: pro úhel {2} platí: a – {3}, b – {4}, c – {5}. sin α, cos α a tan α jsou jejich poměry – závisejí jen na úhlu, ne na velikosti trojúhelníku. Nahoře zvol, co je zadáno.",
