"Im allgemeinen Dreieck gelten der Sinussatz a : sin α = b : sin β = c : sin γ und der Kosinussatz a² = b² + c² − {0}bc·cos α. Den Kosinussatz braucht man bei SSS und SWS, den Sinussatz bei WSW und SSW; bei SSW mit a {1} b kann es zwei Dreiecke geben.": "V obecném trojúhelníku platí sinová věta a : sin α = b : sin β = c : sin γ a kosinová věta a² = b² + c² − {0}bc·cos α. Kosinová věta je potřeba u sss a sus, sinová věta u usu a Ssu; u Ssu s a {1} b mohou existovat dva trojúhelníky.",
