"Die allgemeine Sinusfunktion {0} = a·sin({1}) + d entsteht aus sin x: a streckt (Amplitude |a|, Hochpunkt), b ändert die Periode T = {2}π/b (Periodenende), c verschiebt in x-Richtung (Phase), d in y-Richtung (Mittellinie y = d); Startpunkt {3}.": "Obecná funkce sinus {0} = a·sin({1}) + d vzniká z sin x: a natahuje (amplituda |a|, maximum), b mění periodu T = {2}π/b (konec periody), c posouvá ve směru x (fáze), d ve směru y (střední přímka y = d); počáteční bod {3}.",
"Sinus = Höhe, Kosinus = waagrechter Abstand des Punktes {0} auf dem Einheitskreis; {1}, {2}": "Sinus = výška, kosinus = vodorovná vzdálenost bodu {0} na jednotkové kružnici; {1}, {2}",
"Dreht sich {0} gleichmässig, so beschreibt seine Höhe die Sinuskurve und sein waagrechter Abstand die Kosinuskurve – das Bild rechts.": "Otáčí-li se {0} rovnoměrně, opisuje jeho výška sinusoidu a jeho vodorovná vzdálenost kosinusoidu – obrázek vpravo.",
"<0>Periodizität und Symmetrie:</0> Eine volle Umdrehung ändert nichts; Spiegeln an der {1}-Achse lässt den Sinus gleich, Spiegeln an der {2}-Achse den Kosinus.": "<0>Periodičnost a souměrnost:</0> celá otáčka nic nezmění; při souměrnosti podle osy {1} se nemění sinus, při souměrnosti podle osy {2} kosinus.",
"<0>Pythagoras im Einheitskreis:</0> Die Koordinaten von {1} sind die Katheten eines rechtwinkligen Dreiecks mit Hypotenuse {2}:": "<0>Pythagorova věta v jednotkové kružnici:</0> souřadnice bodu {1} jsou odvěsnami pravoúhlého trojúhelníku s přeponou {2}:",
