"<0>Bogenmass:</0> Statt in Grad misst man den Winkel durch die <1>Länge des Bogens</1> auf dem Einheitskreis. Der ganze Kreis hat den Umfang {2}, also entspricht {3} dem Bogen {4} und {5} dem Bogen {6}.": "<0>Oblouková míra:</0> místo ve stupních se úhel měří <1>délkou oblouku</1> na jednotkové kružnici. Celá kružnice má délku {2}, takže úhlu {3} odpovídá oblouk {4} a úhlu {5} oblouk {6}.",
"<0>Definition:</0> Der Kosinus ist die {1}-Koordinate von {2} (waagrechter Abstand), der Sinus die {3}-Koordinate (Höhe). Weil der Radius {4} ist, stimmt das mit Ankathete/Hypotenuse und Gegenkathete/Hypotenuse im rechtwinkligen Dreieck überein.": "<0>Definice:</0> kosinus je souřadnice {1} bodu {2} (vodorovná vzdálenost), sinus souřadnice {3} (výška). Protože poloměr je {4}, shoduje se to s poměry přilehlá odvěsna/přepona a protilehlá odvěsna/přepona v pravoúhlém trojúhelníku.",
"<0>Einheitskreis:</0> Kreis mit Radius {1} um den Ursprung. Der Winkel {2} wird von der positiven {3}-Achse aus <4>gegen den Uhrzeigersinn</4> gemessen. Der Strahl trifft den Kreis im Punkt {5}.": "<0>Jednotková kružnice:</0> kružnice s poloměrem {1} a středem v počátku. Úhel {2} se měří od kladné poloosy {3} <4>proti směru hodinových ručiček</4>. Polopřímka protne kružnici v bodě {5}.",
