"<0>Zuordnung:</0> Den Faktor, der beim Ableiten einfacher wird, nimmt man als {1}; vom anderen Faktor {2} braucht man eine Stammfunktion {3}.": "<0>Přiřazení:</0> činitel, který se derivováním zjednoduší, zvolíme jako {1}; k druhému činiteli {2} potřebujeme primitivní funkci {3}.",
"<0>Im Bild:</0> Die Kurve mit den Punkten {1} läuft von {2} bis {3}. Die blaue Fläche zwischen Kurve und {4}-Achse ist {5}, die grüne Fläche zwischen Kurve und {6}-Achse ist {7}. Zusammen füllen sie das grosse Rechteck {8} ohne das kleine Rechteck {9}:": "<0>Na obrázku:</0> křivka s body {1} vede od {2} do {3}. Modrá plocha mezi křivkou a osou {4} je {5}, zelená plocha mezi křivkou a osou {6} je {7}. Dohromady vyplní velký obdélník {8} bez malého obdélníku {9}:",
"<0>Regel:</0> Aus der Produktregel {1} folgt durch Integrieren von {2} bis {3}:": "<0>Pravidlo:</0> z pravidla pro součin {1} plyne integrováním od {2} do {3}:",
