"Partielle Integration: ∫ u·v′ dx = [u·v] − ∫ u′·v dx. Im Bild läuft der Punkt ({0} | {1}) für x von a bis b. Die blaue Fläche links der Kurve ist ∫ u dv = ∫ u·v′ dx, die grüne Fläche unter der Kurve ist ∫ v du = ∫ v·u′ dx.": "Integrace per partes: ∫ u·v′ dx = [u·v] − ∫ u′·v dx. Na obrázku se bod ({0} | {1}) pohybuje, když x probíhá od a do b. Modrá plocha vlevo od křivky je ∫ u dv = ∫ u·v′ dx, zelená plocha pod křivkou je ∫ v du = ∫ v·u′ dx.",
"Funktionen u und v (gesucht ∫ u · v′ dx)": "Funkce u a v (hledá se ∫ u · v′ dx)",
