"Ziehe {0}, {1} und {2} auf der {3}: Die {4} ∫ u dv und die {5} ∫ v du ergeben zusammen das grosse Rechteck {6}·{7} ohne das {8} – das ist die partielle Integration.": "Posouvej {0}, {1} a {2} ({3}): {4} ∫ u dv a {5} ∫ v du dávají dohromady velký obdélník {6}·{7} bez {8} – to je integrace per partes.",
