"<0>Im Bild:</0> Links ist die Fläche unter {1} in gleich breite Streifen der Breite {2} geteilt. Die Abbildung {3} in der Mitte bringt jeden Streifen nach rechts unter den Graphen von {4}. Dort ist er {5}-mal so breit, aber nur {6} hoch statt {7}. Die Fläche bleibt gleich. Mit dem Regler «Verformung» sieht man den Übergang fliessend: Jeder Streifen wird {8}-mal so breit und dafür {9}-mal so niedrig.": "<0>Na obrázku:</0> vlevo je plocha pod {1} rozdělena na stejně široké pruhy šířky {2}. Zobrazení {3} uprostřed přenese každý pruh doprava pod graf {4}. Tam je {5}-krát širší, ale vysoký jen {6} místo {7}. Plocha zůstává stejná. Posuvníkem „Deformace“ je přechod vidět plynule: každý pruh se stane {8}-krát širším a za to {9}-krát nižším.",
"<0>Regel:</0> Steht im Integranden eine Verkettung {1} zusammen mit der inneren Ableitung {2}, so ersetzt man {3}:": "<0>Pravidlo:</0> je-li v integrandu složená funkce {1} spolu s derivací vnitřní funkce {2}, zavede se substituce {3}:",
