"Substitution: ∫ f({0}) · g′(x) dx = ∫ {1} du mit u = {2}. Links ist die Fläche von a bis b in gleich breite, farbige Streifen geteilt. In der Mitte bildet u = {3} jede Streifengrenze auf die u-Achse ab, rechts liegen dieselben Streifen unter {4}.": "Substituce: ∫ f({0}) · g′(x) dx = ∫ {1} du, kde u = {2}. Vlevo je plocha od a do b rozdělena na stejně široké barevné pruhy. Uprostřed zobrazí u = {3} každou hranici pruhu na osu u, vpravo leží tytéž pruhy pod {4}.",
"Äussere Funktion f und innere Funktion g (gesucht ∫ f({0}) · g′(x) dx)": "Vnější funkce f a vnitřní funkce g (hledá se ∫ f({0}) · g′(x) dx)",
"violetten Punkt": "fialový bod",
"Ziehe den {0} oder die Grenzen {1} und {2}, oder starte die Verformung: Jeder Streifen unter {3} wird über {4} zu einem Streifen unter {5} – g′(x)-mal so breit, g′(x)-mal so niedrig, gleiche Fläche.": "Posouvej {0} nebo meze {1} a {2}, nebo spusť deformaci: každý pruh pod {3} se pomocí {4} změní na pruh pod {5} – g′(x)-krát širší, g′(x)-krát nižší, se stejnou plochou.",
"Die Fläche zwischen f und der x-Achse (oder zwischen f und g) von a bis b wird an den Schnittstellen in Stücke geteilt. Stücke über der Achse (bzw. über g) sind grün, darunter orange.": "Plocha mezi f a osou x (nebo mezi f a g) od a do b se v průsečících rozdělí na části. Části nad osou (resp. nad g) jsou zelené, pod ní oranžové.",
"Ziehe {0} und {1} (oder wähle «zwischen f und g»): Die Fläche zwischen {2} und der x-Achse bzw. {3} wird an den Schnittstellen geteilt – Stücke darüber sind grün, darunter orange. Flächen zählen immer positiv.": "Posuň {0} a {1} (nebo zvol „mezi f a g“): plocha mezi {2} a osou x, resp. {3}, se rozdělí v průsečících – části nad jsou zelené, pod oranžové. Plochy se vždy počítají kladně.",
"{0} Graph drehen, dann Scheiben": "{0} Otočit graf, potom kotouče",
"Dreht man den Graphen von f zwischen a und b um die x-Achse, entsteht ein Körper aus lauter dünnen Kreisscheiben. Jede Scheibe hat das Volumen π · {0}² · Δx.": "Otáčí-li se graf funkce f mezi a a b kolem osy x, vznikne těleso složené ze samých tenkých kotoučů. Každý kotouč má objem π · {0}² · Δx.",
"Graph von f": "graf funkce f",
"Ziehe {0} und {1} und erhöhe die Zahl der {2} (oder starte «{3} Graph drehen, dann Scheiben»): Der {4} dreht sich um die x-Achse, jede Scheibe hat das Volumen π·{5}²·Δx, und ihre Summe nähert sich V = π ∫ {6}² dx.": "Posuň {0} a {1} a zvyš počet dílů ({2}) (nebo spusť „{3} Otočit graf, potom kotouče“): {4} se otáčí kolem osy x, každý kotouč má objem π·{5}²·Δx a jejich součet se blíží k V = π ∫ {6}² dx.",
"Partielle Integration und Substitution sind als Bild erklärt: Punkte und Grenzen ziehen, bei der Substitution «{0} Streifen in die u-Welt verformen».": "Integrace per partes a substituce jsou vysvětleny obrázkem: posouvej body a meze, u substituce použij „{0} Přetvořit pruhy do světa u“.",
"Flächen: Links wählst du, ob die Fläche zur x-Achse oder zwischen f und g gesucht ist; «Grenzen auf die Nullstellen setzen» hilft beim Start.": "Obsahy: vlevo zvolíš, zda se hledá plocha k ose x, nebo mezi f a g; „Nastavit meze na nulové body“ pomůže na začátku.",
"Integralfunktion und Hauptsatz: Ein Klick ins Bild setzt die Stelle x, an der gestrichelten Linie lässt sie sich ziehen. Ziehen im Bild verschiebt den Ausschnitt (oben f, unten Fa getrennt), das Mausrad bzw. zwei Finger zoomen; Doppelklick oder «⟲ Ausschnitt» stellt den automatischen Ausschnitt wieder her.": "Integrální funkce a základní věta: kliknutím do obrázku nastavíš polohu x, za čárkovanou čáru ji lze posouvat. Tažením v obrázku se posouvá výřez (nahoře f a dole Fa zvlášť), kolečko myši nebo dva prsty přibližují; dvojklik nebo „⟲ Výřez“ obnoví automatický výřez.",
"Ober- und Untersumme: Anzahl n links erhöhen oder «{0} n → ∞» starten; «n = {1}» setzt zurück.": "Horní a dolní součet: zvyš počet n vlevo nebo spusť „{0} n → ∞“; „n = {1}“ vrátí výchozí stav.",
"Die Grenzen a und b ziehst du auf der x-Achse; eine eigene Funktion tippst du ins Feld.": "Meze a a b posouváš po ose x; vlastní funkci napíšeš do pole.",
"Untersumme zeigen (grün)": "Zobrazit dolní součet (zelený)",
"Mit den Grundregeln findet das Programm hier keine Stammfunktion (partielle Integration oder Substitution nötig, oder es gibt keine geschlossene Form); die Integralfunktion wird numerisch berechnet.": "Pomocí základních pravidel zde program primitivní funkci nenajde (bylo by potřeba integrovat per partes nebo substitucí, nebo neexistuje uzavřený tvar); integrální funkce se počítá numericky.",
"Fläche von a bis x färben": "Vybarvit plochu od a do x",
"Mit den Grundregeln (Potenz-, Summen-, Konstantenregel) findet das Programm hier keine Stammfunktion: Dafür bräuchte es partielle Integration oder Substitution, bei manchen Funktionen gibt es gar keine geschlossene Form. Das Integral wird numerisch berechnet.": "Pomocí základních pravidel (pravidlo pro mocninu, součet a konstantu) zde program primitivní funkci nenajde: bylo by potřeba integrovat per partes nebo substitucí a u některých funkcí uzavřený tvar vůbec neexistuje. Integrál se počítá numericky.",
"Mit den Grundregeln (Potenz-, Summen-, Konstantenregel) findet das Programm hier keine Stammfunktion: Dafür bräuchte es partielle Integration oder Substitution (siehe die Ansichten dazu); bei manchen Funktionen wie {0} gibt es gar keine geschlossene Form. Das bestimmte Integral wird numerisch berechnet.": "Pomocí základních pravidel (pravidlo pro mocninu, součet a konstantu) zde program primitivní funkci nenajde: bylo by potřeba integrovat per partes nebo substitucí (viz příslušná zobrazení); u některých funkcí, jako je {0}, uzavřený tvar vůbec neexistuje. Určitý integrál se počítá numericky.",
