"Der Grenzwert lim {0} für x → a ist die Zahl, der sich {1} beliebig nähert, wenn x von links und von rechts gegen a geht – auch wenn f an der Stelle a selbst nicht definiert ist. Ergibt das Einsetzen {2}/{3}, kürzt man zuerst den gemeinsamen Faktor. Für x → ±∞ entscheiden die höchsten Potenzen.": "Limita lim {0} pro x → a je číslo, ke kterému se {1} libovolně blíží, když se x blíží k a zleva i zprava – i když f v samotném bodě a není definována. Vyjde-li po dosazení {2}/{3}, nejprve se zkrátí společný činitel. Pro x → ±∞ rozhodují nejvyšší mocniny.",
