"Ziehe den {0} oder {1} gegen die Stelle {2} (oder drücke «{3} h → {4}»): Die Funktionswerte von links und rechts nähern sich dem {5}. Wähle «x → ±∞», um das Verhalten für grosse x und die waagrechte Asymptote zu sehen.": "Posouvej {0} nebo {1} k bodu {2} (nebo stiskni „{3} h → {4}“): funkční hodnoty zleva i zprava se blíží k jednomu číslu ({5}). Volbou „x → ±∞“ uvidíš chování pro velká x a vodorovnou asymptotu.",
"Beide Grenzwerte sind gleich: {0} ist die Steigung der Tangente.": "Obě limity jsou stejné: {0} je směrnice tečny.",
