"Oben der Graph von f, unten der Graph der Ableitung f′. Ziehe den Punkt: Die Höhe des unteren Punktes ist die Steigung der Tangente oben. Der Ausschnitt richtet sich nach den Nullstellen, Extrem- und Wendepunkten. Ziehen im Bild verschiebt ihn, Mausrad oder zwei Finger zoomen, ein Klick setzt die Stelle; «⟲ Ausschnitt» stellt ihn wieder her.": "Nahoře graf funkce f, dole graf derivace f′. Posouvej bod: výška dolního bodu je směrnice tečny nahoře. Výřez se řídí nulovými body, extrémy a inflexními body. Tažením v obrázku se posouvá, kolečko myši nebo dva prsty přibližují, kliknutím nastavíš polohu; „⟲ Výřez“ jej obnoví.",
"Hoch-, Tief- und Wendepunkten": "maximech, minimech a inflexních bodech",
"Ziehe den {0} entlang von {1} oder lass die Tangente wandern: Die Steigung der {2} oben ist die Höhe des Punktes auf {3} unten. An {4} rastet der Punkt ein, und die Animation wartet, bis du «{5} weiter» drückst.": "Posouvej {0} po {1} nebo nech tečnu putovat: směrnice přímky nahoře ({2}) je výška bodu na {3} dole. V {4} se bod zachytí a animace čeká, dokud nestiskneš „{5} dále“.",
"An dieser Stelle ist die Funktion nicht definiert oder nicht ableitbar.": "V tomto bodě není funkce definována nebo nemá derivaci.",
"Normale": "Normála",
"Gib eine Funktion ein und ziehe den {0} auf dem {1}: Rechts wird f′(x) mit den Ableitungsregeln berechnet, daraus die Steigung und die Gleichung der {2} in P (optional auch {3} und {4}).": "Zadej funkci a posouvej {0} po křivce ({1}): vpravo se f′(x) vypočítá pomocí pravidel derivování a z ní směrnice a rovnice přímky v bodě P ({2}; volitelně také {3} a {4}).",
"Gib eine Funktion ein oder wähle ein Beispiel: Am {0} sind {1}, {2} und {3} markiert, rechts stehen alle Ergebnisse. Der Rechenweg zeigt Schritt für Schritt, wie man sie findet.": "Zadej funkci nebo zvol příklad: na křivce ({0}) jsou vyznačeny {1}, {2} a {3}, vpravo jsou všechny výsledky. Postup ukazuje krok za krokem, jak je najít.",
