"Extremwertprobleme löst man in fünf Schritten: Variable wählen, Nebenbedingung aufstellen, Zielfunktion mit nur einer Variablen und Definitionsbereich angeben, Ableitung null setzen, Art des Extremums prüfen und das Ergebnis deuten.": "Extremální úlohy se řeší v pěti krocích: zvolit proměnnou, sestavit vedlejší podmínku, zapsat účelovou funkci jedné proměnné a její definiční obor, položit derivaci rovnu nule, ověřit druh extrému a výsledek interpretovat.",
