"Das Summenzeichen ist eine Kurzschrift: ∑ von k = m bis n über aₖ bedeutet aₘ + aₘ₊₁ + … + aₙ. Die Laufvariable (meist k, i oder j) durchläuft alle ganzen Zahlen von der unteren bis zur oberen Grenze; es gibt n − m + {0} Summanden. Der Name der Laufvariablen spielt keine Rolle, und man kann den Index verschieben: ∑ von k = {1} bis {2} über (k − {3}) = ∑ von j = {4} bis {5} über j.": "Znak součtu je zkrácený zápis: ∑ od k = m do n z aₖ znamená aₘ + aₘ₊₁ + … + aₙ. Sčítací index (obvykle k, i nebo j) probíhá všechna celá čísla od dolní po horní mez; sčítanců je n − m + {0}. Na názvu indexu nezáleží a index lze posunout: ∑ od k = {1} do {2} z (k − {3}) = ∑ od j = {4} do {5} z j.",
"Summand (Term in k)": "Sčítanec (výraz s k)",
