"Lies das Summenzeichen: Die {0} sagt, bei welchem k du beginnst, die {1}, wo du aufhörst. Den {2} rechnest du für jedes k aus und addierst alle. Ziehe im Bild die Grenzen m und n und die {3}: Der Balken von k leuchtet, oben steht sein Summand. «{4} k von m bis n laufen lassen» addiert die Summanden der Reihe nach.": "Přečti znak součtu: {0} říká, u kterého k začínáš, {1}, kde končíš. Pro každé k se vypočítá {2} a všechno se sečte. V obrázku posouvej meze m a n a {3}: sloupec pro k se rozsvítí a nad ním je jeho sčítanec. „{4} Nechat k proběhnout od m do n“ sčítá sčítance postupně.",
"<0>Trick von Gauss:</0> Die Summe vorwärts und rückwärts untereinander schreiben. Jede Spalte ergibt {1}, und es gibt {2} Spalten: {3}.": "<0>Gaussův trik:</0> součet napsat popředu a pozpátku pod sebe. Každý sloupec dává {1} a počet sloupců je {2}: {3}.",
"<0>Reihe</0> = Summe der ersten {1} Glieder. Mit dem Summenzeichen:": "<0>Řada</0> = součet prvních členů (počet členů: {1}). Pomocí znaku součtu:",
