"Die Summe der ersten n Glieder heisst Reihe: sₙ = a₁ + … + aₙ. Arithmetisch: sₙ = n·(a₁ + aₙ)/{0} (Trick von Gauss), geometrisch: sₙ = a₁·(qⁿ − {1})/(q − {2}).": "Součet prvních n členů se nazývá řada: sₙ = a₁ + … + aₙ. Aritmetická: sₙ = n·(a₁ + aₙ)/{0} (Gaussův trik), geometrická: sₙ = a₁·(qⁿ − {1})/(q − {2}).",
