"Ziehe den {0} im unteren Bild nach links oder rechts, um n zu ändern: Oben kommen {1} dazu oder fallen weg, unten wächst sₙ = a₁ + … + aₙ. Beim Gauss-Trick ergänzt die rückwärts gelesene Folge die Balken zu einem Rechteck («{2} Gauss-Trick als Bewegung» zeigt, wie sie sich umdreht).": "Posouvej {0} v dolním obrázku doleva nebo doprava, a tím měň n: nahoře přibývají nebo ubývají {1}, dole roste sₙ = a₁ + … + aₙ. U Gaussova triku doplní posloupnost čtená pozpátku sloupce na obdélník („{2} Gaussův trik jako pohyb“ ukáže, jak se obrátí).",
