"Bei Brüchen Zähler und Nenner durch die höchste Potenz von {0} teilen; dann gehen Terme wie {1} gegen {2}.": "U zlomků vydělit čitatele i jmenovatele nejvyšší mocninou {0}; výrazy jako {1} se pak blíží k {2}.",
"<0>Konvergent:</0> Für grosse {1} kommen die Glieder der Zahl {2} beliebig nahe.": "<0>Konvergentní:</0> pro velká {1} se členy libovolně blíží k číslu {2}.",
