"Kommen die Glieder für grosse n einer Zahl beliebig nahe, ist das der Grenzwert. Zu jedem ε gibt es ein N, ab dem alle Glieder im ε-Streifen liegen. Eine unendliche geometrische Reihe hat für |q| {0} {1} den Wert a₁/({2} − q).": "Blíží-li se členy pro velká n libovolně k nějakému číslu, je toto číslo limitou. Ke každému ε existuje N, od kterého leží všechny členy v ε-pásu. Nekonečná geometrická řada má pro |q| {0} {1} hodnotu a₁/({2} − q).",
