"Ziehe den {0}, um den {1} um den {2} schmaler zu machen: Ab einem Index N liegen alle Glieder im Streifen – je kleiner ε, desto weiter rechts liegt N. Mit «{3} Animation: ε → {4}» wird der Streifen immer schmaler, und es kommen immer mehr Glieder dazu.": "Posouvej {0}, a tím zužuj {1} kolem limitní hodnoty ({2}): od jistého indexu N leží všechny členy v pásu – čím menší ε, tím více vpravo leží N. S „{3} Animace: ε → {4}“ se pás stále zužuje a přibývá stále více členů.",
