"Wähle eine Aussage und lass mit «Schritt» die Dominosteine fallen: Gilt {0} und folgt aus {1} stets {2}, dann gilt die Aussage für alle n. Die letzte Aussage zeigt, warum Beispiele allein nichts beweisen.": "Zvol tvrzení a tlačítkem „Krok“ nech padat kostky domina: platí-li {0} a z {1} vždy plyne {2}, pak tvrzení platí pro všechna n. Poslední tvrzení ukazuje, proč samotné příklady nic nedokazují.",
