"Die Reihe rückwärts darunter schreiben: Jede Spalte ergibt {0}, und es sind {1} Spalten. Das ist die Summe zweimal, also s = {2} · {3} / {4}. Dieselbe Idee steckt in der Formel sₙ = n · (a₁ + aₙ) / {5}.": "Řadu napsat pozpátku pod sebe: každý sloupec dává {0} a počet sloupců je {1}. To je součet dvakrát, tedy s = {2} · {3} / {4}. Stejná myšlenka je ve vzorci sₙ = n · (a₁ + aₙ) / {5}.",
"Der Legende nach stellte der Lehrer Büttner um {0} seiner Klasse die Aufgabe, alle Zahlen von {1} bis {2} zu addieren – er wollte eine Weile Ruhe. Der neunjährige Carl Friedrich Gauss war nach wenigen Augenblicken fertig:": "Podle legendy zadal učitel Büttner kolem roku {0} své třídě úkol sečíst všechna čísla od {1} do {2} – chtěl mít chvíli klid. Devítiletý Carl Friedrich Gauss byl hotov za pár okamžiků:",
