"Intervall:": "Interval:",
"Das Intervall ist <0>beschränkt</0>; seine Länge ist {1}.": "Interval je <0>omezený</0>; jeho délka je {1}.",
"Ein <0>Intervall</0> ist die Menge aller reellen Zahlen zwischen zwei Randpunkten. Eckige Klammer {1}: Randpunkt gehört dazu; runde Klammer {2}: gehört nicht dazu. Bei {3} ist die Klammer immer offen.": "<0>Interval</0> je množina všech reálných čísel mezi dvěma krajními body. Hranatá závorka {1}: krajní bod do intervalu patří; kulatá závorka {2}: nepatří. U {3} je závorka vždy otevřená.",
"Intervall und Schreibweisen": "Interval a zápisy",
"Rechenweg: Intervall": "Postup: Interval",
"gefüllter Punkt: Rand gehört dazu, leerer Punkt: gehört nicht dazu": "plný bod: krajní bod patří, prázdný bod: nepatří",
