"Ziehe die {0} auf der Zahlengeraden und lege links fest, ob sie {1} oder bis ±∞ reichen: Das {2} erscheint in Intervallschreibweise, als Ungleichung und in Mengenschreibweise.": "Posouvej {0} na číselné ose a vlevo urči, zda {1}, nebo sahají až do ±∞: {2} se zobrazí v intervalovém zápisu, jako nerovnost a v množinovém zápisu.",
"{0} Ziehe die Randpunkte im Bild. Links wählst du offen oder geschlossen, unendlich und die Operation; rechts steht der Rechenweg.": "{0} Posouvej krajní body v obrázku. Vlevo volíš otevřený nebo uzavřený, nekonečný a operaci; vpravo je postup.",
"Alle Operationen auf einen Blick:": "Všechny operace přehledně:",
"<0>Vorgehen:</0> Beide Intervalle untereinander auf der Zahlengeraden einzeichnen, die gesuchten Bereiche ablesen und bei jedem Randpunkt prüfen, ob er dazugehört.": "<0>Postup:</0> oba intervaly zakreslit pod sebe na číselnou osu, odečíst hledané části a u každého krajního bodu ověřit, zda patří.",
"Die <0>Schnittmenge</0> {1} enthält alle Zahlen, die in {2} <3>und</3> in {4} liegen.": "<0>Průnik</0> {1} obsahuje všechna čísla, která leží v {2} <3>i</3> v {4}.",
