"Mit Intervallen rechnet man wie mit Mengen: A ∩ B (und), A ∪ B (oder), A \\ B (ohne) und das Komplement Ā (alle anderen reellen Zahlen). Am einfachsten zeichnet man beide Intervalle untereinander und liest das Ergebnis ab; an jedem Randpunkt entscheidet man, ob er dazugehört.": "S intervaly se počítá jako s množinami: A ∩ B (a), A ∪ B (nebo), A \\ B (bez) a doplněk Ā (všechna ostatní reálná čísla). Nejjednodušší je zakreslit oba intervaly pod sebe a výsledek odečíst; u každého krajního bodu se rozhodne, zda patří.",
"Ergebnismenge": "výsledná množina",
"Ziehe die Randpunkte von {0} und {1} und wähle eine Operation: Die {2} zeigt, welche Zahlen in A und B liegen (Schnittmenge), in A oder B (Vereinigung), in A, aber nicht in B (Differenz) oder nicht in A (Komplement).": "Posouvej krajní body intervalů {0} a {1} a zvol operaci: {2} ukazuje, která čísla leží v A i B (průnik), v A nebo B (sjednocení), v A, ale ne v B (rozdíl), nebo neleží v A (doplněk).",
