"Vereinigung A ∪ B: in A oder B. Schnitt A ∩ B: in A und B. Differenz A \\ B: in A, aber nicht in B. Komplement Ā: in G, aber nicht in A. Bei drei Mengen gibt es acht Felder; man füllt sie von der Mitte nach aussen. Gesetze von De Morgan: (A ∪ B)‾ = Ā ∩ B̄ und (A ∩ B)‾ = Ā ∪ B̄.": "Sjednocení A ∪ B: v A nebo B. Průnik A ∩ B: v A i B. Rozdíl A \\ B: v A, ale ne v B. Doplněk Ā: v G, ale ne v A. U tří množin je osm oblastí; vyplňují se od středu ven. De Morganovy zákony: (A ∪ B)‾ = Ā ∩ B̄ a (A ∩ B)‾ = Ā ∪ B̄.",
"Grundmenge G": "základní množina G",
"Feldern": "oblastech",
"schraffierten Felder": "vyšrafované oblasti",
"Wähle links eine Operation oder tippe einen Term wie (A ∪ B) ∩ C: Die {0} bilden die Ergebnismenge («{1} Term Schritt für Schritt schraffieren» baut sie von innen nach aussen auf). Mit Elementen oder Anzahlen in den {2} liest du das Ergebnis direkt ab; die Mengen {3}, {4} und {5} liegen in der {6}.": "Vlevo zvol operaci nebo napiš výraz, např. (A ∪ B) ∩ C: {0} tvoří výslednou množinu („{1} Vyšrafovat výraz krok za krokem“ ji sestaví zevnitř ven). S prvky nebo počty v {2} odečteš výsledek přímo; množiny {3}, {4} a {5} obsahuje {6}.",
"Tipp: Zuerst die Klammern. Ein Feld gehört dazu, wenn seine Punkte die Bedingung erfüllen.": "Tip: nejprve závorky. Oblast do množiny patří, když její body splňují podmínku.",
"Schraffiere": "Vyšrafuj",
"Auswahl löschen": "Smazat výběr",
"Klicke im Bild auf ein Feld, um es zu schraffieren; nochmals klicken entfernt die Schraffur.": "Klikni v obrázku na oblast, a tím ji vyšrafuješ; dalším kliknutím šrafování zrušíš.",
"Schraffiere {0}: Klicke im Venn-Diagramm die Felder an.": "Vyšrafuj {0}: klikej na oblasti ve Vennově diagramu.",
