"Aufgabe": "Úloha",
"Übungen zu Intervallen (Schreibweisen, Schnitt, Vereinigung, Differenz, Komplement) und zu Mengenoperationen mit zwei oder drei Mengen im Venn-Diagramm. Jede Aufgabe wird neu erzeugt; «Lösung zeigen» zeigt den Weg.": "Cvičení na intervaly (zápisy, průnik, sjednocení, rozdíl, doplněk) a na množinové operace se dvěma nebo třemi množinami ve Vennově diagramu. Každá úloha se vytvoří nově; „Ukázat řešení“ ukáže postup.",
"Venn-Diagramm": "Vennův diagram",
"Wähle links die Aufgabenart und löse die Aufgabe: Tippe die Antwort ein oder klicke im {0} die Felder an, die zur Menge gehören. «Prüfen» zeigt, ob es stimmt; danach steht rechts der Lösungsweg.": "Vlevo zvol druh úlohy a vyřeš ji: napiš odpověď nebo v obrázku ({0}) klikni na oblasti, které do množiny patří. „Zkontrolovat“ ukáže, zda je to správně; potom je vpravo řešení.",
"Übungen: Aufgabenart wählen, Antwort eintippen oder Felder anklicken, dann «Prüfen». «Lösung zeigen» und «Neue Aufgabe» stehen daneben.": "Cvičení: zvol druh úlohy, napiš odpověď nebo klikni na oblasti, potom „Zkontrolovat“. „Ukázat řešení“ a „Nová úloha“ jsou vedle.",
"Venn-Diagramm: Operation wählen oder einen eigenen Term mit den Tasten A, B, ∪, ∩, \\ und Ā eingeben; {0} oder {1} Mengen, Felder mit Elementen oder Anzahlen.": "Vennův diagram: zvol operaci nebo zadej vlastní výraz pomocí kláves A, B, ∪, ∩, \\ a Ā; {0} nebo {1} množiny, oblasti s prvky nebo počty.",
"Die Schreibweise offener Intervalle ist wählbar: runde Klammer (a, b) oder nach aussen gedrehte eckige Klammer.": "Zápis otevřených intervalů lze zvolit: kulatá závorka (a, b) nebo hranatá závorka otočená ven.",
"Randpunkte auf der Zahlengeraden ziehen; links legst du fest, ob ein Rand dazugehört («gehört dazu») oder das Intervall bis −∞ bzw. ∞ reicht.": "Posouvej krajní body na číselné ose; vlevo určíš, zda krajní bod patří („patří“), nebo zda interval sahá do −∞, případně ∞.",
"Das Intervall ist <0>unbeschränkt</0> (es reicht bis ins Unendliche).": "Interval je <0>neomezený</0> (sahá do nekonečna).",
"Ein <0>Intervall</0> ist die Menge aller reellen Zahlen zwischen zwei Randpunkten. Eckige Klammer {1}: Randpunkt gehört dazu; nach aussen gedreht {2}: gehört nicht dazu. Bei {3} ist die Klammer immer offen.": "<0>Interval</0> je množina všech reálných čísel mezi dvěma krajními body. Hranatá závorka {1}: krajní bod do intervalu patří; závorka otočená ven {2}: nepatří. U {3} je závorka vždy otevřená.",
"Mengenoperation": "Množinová operace",
"Das Ergebnis besteht aus {0} getrennten Teilen.": "Výsledek se skládá z {0} oddělených částí.",
"Die <0>Vereinigungsmenge</0> {1} enthält alle Zahlen, die in {2} <3>oder</3> in {4} (oder in beiden) liegen.": "<0>Sjednocení</0> {1} obsahuje všechna čísla, která leží v {2} <3>nebo</3> v {4} (nebo v obou).",
