"Gib links die Geraden g und h in Parameterform ein und drehe den Raum: Schneiden sie sich im {0}, sind sie parallel oder {1}? Die {2} entscheiden zuerst. Mit den Reglern t und s (oder «{3} t und s laufen lassen») wandern die Punkte {4} und {5} auf den Geraden: Jeder Parameterwert gibt genau einen Punkt.": "Vlevo zadej přímky g a h v parametrickém tvaru a otáčej prostorem: mají společný {0}, jsou rovnoběžné, nebo {1}? Nejprve rozhodují {2}. Posuvníky t a s (nebo „{3} Měnit t a s“) se body {4} a {5} pohybují po přímkách: každá hodnota parametru dává právě jeden bod.",
"Gerade in Parameterform: X = P + t·u mit Stützpunkt P und Richtungsvektor u. Zwei Geraden sind identisch, echt parallel, schneidend oder windschief. Prüfen: Sind u und v Vielfache? Sonst gleichsetzen: zwei Gleichungen lösen, die dritte prüfen.": "Přímka v parametrickém tvaru: X = P + t·u s bodem P a směrovým vektorem u. Dvě přímky jsou totožné, rovnoběžné různé, různoběžné nebo mimoběžné. Ověřit: jsou u a v násobky? Jinak porovnat: vyřešit dvě rovnice, třetí ověřit.",
