"Gib links die Vektoren a und b ein und drehe den Raum: Der {0} zwischen ihnen folgt aus dem Skalarprodukt. Ist a · b = {1}, stehen sie senkrecht. Das {2} steht senkrecht auf beiden.": "Vlevo zadej vektory a a b a otáčej prostorem: {0} mezi nimi plyne ze skalárního součinu. Je-li a · b = {1}, jsou kolmé. {2} je kolmý na oba.",
"Skalarprodukt: a · b = a₁b₁ + a₂b₂ + a₃b₃ = |a|·|b|·cos φ. Daraus der Winkel: cos φ = a · b / (|a|·|b|). Senkrecht genau dann, wenn a · b = {0}. Vektorprodukt a × b: senkrecht zu a und b, Länge = Fläche des Parallelogramms.": "Skalární součin: a · b = a₁b₁ + a₂b₂ + a₃b₃ = |a|·|b|·cos φ. Z toho úhel: cos φ = a · b / (|a|·|b|). Kolmé právě tehdy, když a · b = {0}. Vektorový součin a × b: kolmý na a i b, délka = obsah rovnoběžníku.",
