"Abstand Punkt–Ebene mit der Hesseschen Normalform: d = |a·x₀ + b·y₀ + c·z₀ − d| / |n|. Abstand Punkt–Gerade: Lotfusspunkt F auf der Geraden so, dass XF senkrecht zum Richtungsvektor steht, dann d = |XF|.": "Vzdálenost bod–rovina pomocí Hesseova normálového tvaru: d = |a·x₀ + b·y₀ + c·z₀ − d| / |n|. Vzdálenost bod–přímka: pata kolmice F na přímce tak, aby XF bylo kolmé na směrový vektor; potom d = |XF|.",
