"Kugel mit Mittelpunkt {0} und Radius r: (x − m₁)² + (y − m₂)² + (z − m₃)² = r². Lage eines Punktes: Abstand zu M mit r vergleichen. Lage einer Ebene: Abstand d von M zur Ebene; für d {1} r Schnittkreis mit Radius √(r² − d²).": "Kulová plocha se středem {0} a poloměrem r: (x − m₁)² + (y − m₂)² + (z − m₃)² = r². Poloha bodu: porovnat vzdálenost od M s r. Poloha roviny: vzdálenost d bodu M od roviny; pro d {1} r průsečná kružnice s poloměrem √(r² − d²).",
"In den anderen Ansichten gibst du Punkte, Vektoren und Geraden links als Koordinaten ein; die Beispiele füllen die Felder aus.": "V ostatních zobrazeních zadáváš vlevo body, vektory a přímky jako souřadnice; příklady pole vyplní.",
