"<0>Planungspolygon</0> = Durchschnitt aller Halbebenen. Seine <1>Eckpunkte</1> sind Schnittpunkte von je zwei Grenzgeraden:": "<0>Mnohoúhelník přípustných řešení</0> = průnik všech polorovin. Jeho <1>vrcholy</1> jsou průsečíky vždy dvou hraničních přímek:",
