"Mehrere Ungleichungen gleichzeitig: Die Lösungsmenge ist der Durchschnitt der Halbebenen, das Planungspolygon. Seine Eckpunkte sind Schnittpunkte von zwei Grenzgeraden.": "Několik nerovnic současně: množinou řešení je průnik polorovin, mnohoúhelník přípustných řešení. Jeho vrcholy jsou průsečíky dvou hraničních přímek.",
"Planungspolygon": "Mnohoúhelník přípustných řešení",
"Gib die Ungleichungen ein (eine pro Zeile) und ziehe den {0}: Er ist zulässig, wenn er im {1} liegt, dem Durchschnitt aller Halbebenen. Die Eckpunkte sind Schnittpunkte von zwei Grenzgeraden.": "Zadej nerovnice (jednu na řádek) a táhni {0}: je přípustný, když ho obsahuje {1}, tedy průnik všech polorovin. Vrcholy jsou průsečíky dvou hraničních přímek.",
