"Nach jeder Antwort siehst du, ob sie stimmt, und die Begründung dazu.": "Po každé odpovědi uvidíš, zda je správná, i se zdůvodněním.",
"Du beantwortest zuerst alle Fragen. Ausgewertet wird am Schluss.": "Nejprve odpovíš na všechny otázky. Vyhodnocení přijde na konci.",
