"Gut gemacht. Schau dir unten an, was noch nicht stimmt.": "Dobrá práce. Podívej se níže, co ještě není správně.",
"Ein guter Anfang. Die Begründungen unten zeigen, wo es noch hakt.": "Dobrý začátek. Zdůvodnění níže ukazují, kde to ještě vázne.",
"Da ist noch Luft nach oben. Arbeite die Ansicht nochmals durch und lies die Begründungen unten.": "Je tu ještě co zlepšovat. Projdi si pohled znovu a přečti si zdůvodnění níže.",
