"Marchzins: Zeitstrahl und Konten": "Alikvotní úrok: časová osa a účty",
"Trage links jede {0} mit ihrem Datum ein: Jede liegt auf einem {1} und trägt Marchzins bis zum {2}. Die {3} zeigt Zinstage und Zins je Konto, am Schluss werden {4}. «{5} Zinsen wachsen lassen» zeigt, wie der Zins Tag für Tag dazukommt.": "Vlevo zadej každý {0} s datem: každý leží na {1} a nese alikvotní úrok až do {2}. {3} ukazuje úrokové dny a úrok pro každý účet, nakonec se {4}. „{5} Nechat úroky růst“ ukazuje, jak úrok přibývá den po dni.",
"Ein- oder Auszahlung": "vklad nebo výběr",
"eigenen Konto": "vlastním účtu",
"Stichtag": "rozhodného dne",
"Tabelle": "Tabulka",
"Kapital und Zinsen addiert": "kapitál a úroky sečtou",
"Prinzip der verschiedenen Konti beim Marchzins: Der Saldo am Jahresanfang und jede Ein- oder Auszahlung werden wie ein eigenes Konto behandelt. Jedes trägt Zins für seine Zinstage bis zum Stichtag (Monat = {0} Tage, Jahr = {1} Tage). Eine Auszahlung zählt als Konto mit negativem Betrag, ihr Zins wird abgezogen. Kapital und Zinsen zusammen ergeben den Saldo am Stichtag.": "Princip oddělených účtů u alikvotního úroku: zůstatek na začátku roku a každý vklad nebo výběr se berou jako samostatný účet. Každý nese úrok za své úrokové dny až do rozhodného dne (měsíc = {0} dní, rok = {1} dní). Výběr se počítá jako účet se zápornou částkou, jeho úrok se odečte. Kapitál a úroky dohromady dávají zůstatek k rozhodnému dni.",
