"Zeitstrahl eines Jahres: Einzahlungen oben, Auszahlungen unten (Klick auf einen Monat: Zahlung hinzufügen)": "Časová osa jednoho roku: vklady nahoře, výběry dole (klikni na měsíc: přidat platbu)",
