"positive reelle Achse:": "kladná reálná poloosa:",
"{0} hat den Betrag {1} und das Argument {2}": "{0} má absolutní hodnotu {1} a argument {2}",
"<0>Konjugierte Zahl:</0> {1} hat denselben Realteil und den entgegengesetzten Imaginärteil. Das Produkt {2} ist reell.": "<0>Komplexně sdružené číslo:</0> {1} má stejnou reálnou část a opačnou imaginární část. Součin {2} je reálný.",
"<0>Polarform:</0> Mit dem Betrag {1} und dem Winkel {2} gilt {3} und {4}.": "<0>Goniometrický tvar:</0> s absolutní hodnotou {1} a úhlem {2} platí {3} a {4}.",
"<0>Argument:</0> Der Winkel {1} wird von der positiven reellen Achse aus im Gegenuhrzeigersinn gemessen. Der Taschenrechner liefert aus {2} nur Winkel zwischen {3} und {4}; der Quadrant von {5} entscheidet, was dazukommt.": "<0>Argument:</0> úhel {1} se měří od kladné reálné poloosy proti směru hodinových ručiček. Z {2} dává kalkulačka jen úhly mezi {3} a {4}; o tom, co se přičte, rozhoduje kvadrant čísla {5}.",
"<0>Betrag:</0> Der Zeiger ist die Hypotenuse eines rechtwinkligen Dreiecks mit den Katheten {1} und {2} (Satz des Pythagoras).": "<0>Absolutní hodnota:</0> šipka je přeponou pravoúhlého trojúhelníku s odvěsnami {1} a {2} (Pythagorova věta).",
"<0>Normalform:</0> {1} mit dem Realteil {2} und dem Imaginärteil {3}; für die imaginäre Einheit gilt {4}.": "<0>Algebraický tvar:</0> {1} s reálnou částí {2} a imaginární částí {3}; pro imaginární jednotku platí {4}.",
