"Ziehe die {0} in der Gauss-Ebene: Ihr {1} ist die Koordinate nach rechts, ihr {2} die Koordinate nach oben. Der {3} ist die Länge des Zeigers, das {4} sein Winkel zur positiven reellen Achse. Die {5} liegt gespiegelt an der reellen Achse.": "Táhni {0} v Gaussově rovině: jeho {1} je souřadnice doprava, jeho {2} souřadnice nahoru. {3} je délka šipky, {4} její úhel s kladnou reálnou poloosou. Souměrně podle reálné osy leží {5}.",
"{0} Ziehe die farbigen Punkte in der Gauss-Ebene: Zeiger, Winkel und Rechenweg rechnen mit. Links wählst du die Ansicht.": "{0} Táhni barevné body v Gaussově rovině: šipky, úhly i postup výpočtu se přepočítají. Vlevo zvolíš pohled.",
"liegt auf der imaginären Achse": "leží na imaginární ose",
"Für {0} ist kein Winkel festgelegt.": "Pro {0} není úhel určen.",
"Mit diesen Werten lässt sich kein Bild zeichnen.": "S těmito hodnotami nelze obrázek nakreslit.",
"Eine komplexe Zahl z = a + bi besteht aus zwei reellen Zahlen: dem Realteil a und dem Imaginärteil b. Die imaginäre Einheit i erfüllt i² = −{0}. Man zeichnet z als Punkt (a | b) oder als Zeiger vom Ursprung aus. Die Polarform beschreibt denselben Punkt durch Betrag und Winkel.": "Komplexní číslo z = a + bi tvoří dvě reálná čísla: reálná část a a imaginární část b. Pro imaginární jednotku i platí i² = −{0}. Číslo z se kreslí jako bod (a | b) nebo jako šipka z počátku. Goniometrický tvar popisuje tentýž bod absolutní hodnotou a úhlem.",
"Gauss-Ebene mit Betrag und Argument, Addieren und Subtrahieren als Zeiger, Multiplizieren und Dividieren als Drehstreckung, Potenzen (Moivre), Wurzeln und Einheitswurzeln, quadratische Gleichungen mit komplexen Lösungen": "Gaussova rovina s absolutní hodnotou a argumentem, sčítání a odčítání šipek, násobení a dělení jako otočení s natažením, mocniny (Moivre), odmocniny a odmocniny z jedné, kvadratické rovnice s komplexními řešeními",
"Komplexe Zahlen": "Komplexní čísla",
