"−{0} − {1}i ({2}. Quadrant)": "−{0} − {1}i ({2}. kvadrant)",
"−{0} + {1}i ({2}. Quadrant)": "−{0} + {1}i ({2}. kvadrant)",
"Quadratische Gleichungen": "Kvadratické rovnice",
"Wurzeln und Einheitswurzeln": "Odmocniny a odmocniny z jedné",
"Potenzen (Formel von Moivre)": "Mocniny (Moivreova věta)",
"Multiplizieren und Dividieren": "Násobení a dělení",
"Addieren und Subtrahieren": "Sčítání a odčítání",
"Zahl in der Gauss-Ebene": "Číslo v Gaussově rovině",
"Ist die Diskriminante negativ, zieht man die Wurzel mit Hilfe der imaginären Einheit. Jede quadratische Gleichung mit reellen Koeffizienten hat damit zwei Lösungen (oder eine doppelte). Die Sätze von Vieta für Summe und Produkt der Lösungen gelten weiter.": "Je-li diskriminant záporný, odmocňuje se pomocí imaginární jednotky. Každá kvadratická rovnice s reálnými koeficienty má pak dvě řešení (nebo jedno dvojnásobné). Vietovy vzorce pro součet a součin řešení platí dál.",
"Aus der Formel von Moivre folgt: Alle n-ten Wurzeln von w haben denselben Betrag, und ihre Winkel unterscheiden sich um den n-ten Teil des Vollwinkels. Für w = {0} heissen sie Einheitswurzeln.": "Z Moivreovy věty plyne: všechny n-té odmocniny z w mají stejnou absolutní hodnotu a jejich úhly se liší o n-tinu plného úhlu. Pro w = {0} se jim říká odmocniny z jedné.",
"Formel von Moivre: Die n-te Potenz hat den n-fachen Winkel, und ihr Betrag ist die n-te Potenz des Betrags. Ist der Betrag grösser als {0}, laufen die Potenzen auf einer Spirale nach aussen, ist er kleiner als {1}, nach innen.": "Moivreova věta: n-tá mocnina má n-násobný úhel a její absolutní hodnota je n-tou mocninou absolutní hodnoty. Je-li absolutní hodnota větší než {0}, běží mocniny po spirále ven; je-li menší než {1}, dovnitř.",
"Gerechnet wird wie mit Klammern, mit i² = −{0}. In der Polarform ist das Produkt eine Drehstreckung: Beträge multiplizieren, Winkel addieren. Beim Dividieren ist es umgekehrt: Beträge dividieren, Winkel subtrahieren; in der Normalform erweitert man mit der konjugierten Zahl des Nenners.": "Počítá se jako se závorkami, přičemž i² = −{0}. V goniometrickém tvaru je součin otočení s natažením: absolutní hodnoty se násobí, úhly sčítají. U dělení je to naopak: absolutní hodnoty se dělí, úhly odčítají; v algebraickém tvaru se zlomek rozšíří číslem komplexně sdruženým ke jmenovateli.",
"Komplexe Zahlen addiert und subtrahiert man getrennt nach Realteil und Imaginärteil, genau wie Vektoren in der Ebene. Der Betrag der Differenz ist der Abstand der beiden Punkte.": "Komplexní čísla se sčítají a odčítají zvlášť v reálné a v imaginární části, stejně jako vektory v rovině. Absolutní hodnota rozdílu je vzdálenost obou bodů.",
"Bei «Wurzeln» kannst du jede Lösung ziehen: Die Zahl w wird dann als n-te Potenz dieser Lösung neu berechnet.": "V pohledu „Odmocniny“ můžeš táhnout kterékoli řešení: číslo w se pak znovu vypočítá jako n-tá mocnina tohoto řešení.",
"Die Punkte rasten beim Ziehen auf runden Werten ein; genaue Werte tippst du links in die Felder.": "Při tažení se body přichytávají ke kulatým hodnotám; přesné hodnoty zapíšeš do polí vlevo.",
"Die Beträge darf man nicht einfach addieren: {0} (Dreiecksungleichung). Hier: {1}.": "Absolutní hodnoty nelze jednoduše sečíst: {0} (trojúhelníková nerovnost). Zde: {1}.",
"<0>Im Bild:</0> Der Zeiger {1} wird an die Spitze von {2} gehängt. Die Summe ist die Diagonale des Parallelogramms mit den Seiten {3} und {4}.": "<0>Na obrázku:</0> šipka {1} se připojí k hrotu {2}. Součet je úhlopříčka rovnoběžníku se stranami {3} a {4}.",
"<0>Getrennt rechnen:</0> Realteile und Imaginärteile werden je für sich addiert.": "<0>Počítáme zvlášť:</0> reálné části a imaginární části se sčítají každé zvlášť.",
"<0>Getrennt rechnen:</0> Realteile und Imaginärteile werden je für sich subtrahiert.": "<0>Počítáme zvlášť:</0> reálné části a imaginární části se odčítají každé zvlášť.",
