"Ziehe {0} und {1}: Die {2} entsteht, indem man den zweiten Zeiger an die Spitze des ersten hängt ({3}). Beim Subtrahieren wird die Gegenzahl −z₂ angehängt.": "Táhni {0} a {1}: {2} vznikne připojením druhé šipky k hrotu první ({3}). Při odčítání se připojí opačné číslo −z₂.",
"<0>Abstand:</0> Die Differenz ist der Zeiger von {1} nach {2}; ihr Betrag ist der Abstand der beiden Punkte.": "<0>Vzdálenost:</0> rozdíl je šipka z {1} do {2}; jeho absolutní hodnota je vzdálenost obou bodů.",
"<0>Im Bild:</0> Subtrahieren heisst, die Gegenzahl {1} zu addieren. Der Zeiger {2} wird an die Spitze von {3} gehängt.": "<0>Na obrázku:</0> odčítat znamená přičíst opačné číslo {1}. Šipka {2} se připojí k hrotu {3}.",
"<0>Im Bild:</0> Multiplizieren mit {1} dreht den Zeiger {2} um {3} und streckt ihn mit dem Faktor {4} (Drehstreckung). Das Dreieck {5} ist ähnlich zum Dreieck {6}.": "<0>Na obrázku:</0> násobení číslem {1} otočí šipku {2} o {3} a natáhne ji činitelem {4} (otočení s natažením). Trojúhelník {5} je podobný trojúhelníku {6}.",
"<0>Polarform:</0> Beträge multiplizieren, Winkel addieren.": "<0>Goniometrický tvar:</0> absolutní hodnoty se násobí, úhly sčítají.",
"<0>Polarform:</0> Beträge dividieren, Winkel subtrahieren.": "<0>Goniometrický tvar:</0> absolutní hodnoty se dělí, úhly odčítají.",
"<0>Ausmultiplizieren:</0> Jeder Summand wird mit jedem multipliziert, dann setzt man {1} ein.": "<0>Roznásobení:</0> každý člen se vynásobí každým, pak se dosadí {1}.",
