"Ziehe {0} und {1}: Beim {2} werden die Beträge multipliziert und die {3}. Die beiden {4} sind ähnlich, denn Multiplizieren mit z₂ dreht um den Winkel von z₂ und streckt mit dessen Betrag. «{5} Drehen und strecken» zeigt die Bewegung.": "Táhni {0} a {1}: u {2} se absolutní hodnoty násobí a {3}. Oba {4} jsou podobné, protože násobení číslem z₂ otáčí o úhel čísla z₂ a natahuje podle jeho absolutní hodnoty. „{5} Otočit a natáhnout“ ukáže pohyb.",
"Winkel ab {0} werden um {1} verkleinert: {2}.": "Úhly od {0} výše se zmenší o {1}: {2}.",
"Negative Winkel werden um {0} vergrössert: {1}.": "Záporné úhly se zvětší o {0}: {1}.",
"<0>Im Bild:</0> Dividieren durch {1} dreht den Zeiger {2} um {3} zurück und staucht ihn mit dem Faktor {4}. Das Dreieck {5} ist ähnlich zum Dreieck {6}.": "<0>Na obrázku:</0> dělení číslem {1} otočí šipku {2} o {3} zpět a zkrátí ji činitelem {4}. Trojúhelník {5} je podobný trojúhelníku {6}.",
"<0>Mit der konjugierten Zahl erweitern:</0> So wird der Nenner reell, denn {1}.": "<0>Rozšíříme číslem komplexně sdruženým:</0> jmenovatel tak bude reálný, protože {1}.",
"Durch {0} kann man nicht dividieren. Wähle {1}.": "Číslem {0} nelze dělit. Zvol {1}.",
"Wegen {0} wachsen die Beträge: Die Potenzen laufen auf einer Spirale nach aussen.": "Protože {0}, absolutní hodnoty rostou: mocniny běží po spirále ven.",
"Wegen {0} schrumpfen die Beträge: Die Potenzen laufen auf einer Spirale nach innen.": "Protože {0}, absolutní hodnoty klesají: mocniny běží po spirále dovnitř.",
"Wegen {0} bleiben alle Potenzen auf dem Einheitskreis.": "Protože {0}, zůstávají všechny mocniny na jednotkové kružnici.",
"<0>Schritt für Schritt:</0> Jede Multiplikation mit {1} dreht um {2} weiter und streckt mit dem Faktor {3}.": "<0>Krok za krokem:</0> každé násobení číslem {1} otočí dál o {2} a natáhne činitelem {3}.",
"<0>Formel von Moivre:</0> Beim Potenzieren wird der Betrag potenziert und der Winkel vervielfacht.": "<0>Moivreova věta:</0> při umocňování se absolutní hodnota umocní a úhel vynásobí.",
