"Ziehe {0} und wähle den Exponenten: Jede {1} dreht um den {2} weiter und streckt mit demselben Faktor. Liegt z auf dem {3}, bleiben alle Potenzen darauf.": "Táhni {0} a zvol exponent: každá {1} otočí dál o {2} a natáhne stejným činitelem. Leží-li z na {3}, zůstávají na ní všechny mocniny.",
"Die Gleichung {0} hat {1} Lösungen mit dem Betrag {2}": "Rovnice {0} má {1} řešení s absolutní hodnotou {2}",
"<0>Im Bild:</0> Die Lösungen liegen auf einem Kreis um {1} und teilen ihn in {2} gleiche Teile. Benachbarte Lösungen schliessen den Winkel {3} ein.": "<0>Na obrázku:</0> řešení leží na kružnici se středem {1} a dělí ji na {2} stejných dílů. Sousední řešení svírají úhel {3}.",
"<0>Ansatz in Polarform:</0> Aus {1} folgt für die Beträge {2} und für die Winkel {3}.": "<0>Postup v goniometrickém tvaru:</0> z {1} plyne pro absolutní hodnoty {2} a pro úhly {3}.",
"Grad n der Wurzel": "Stupeň n odmocniny",
