"Stelle {0} und Zuwachs pro Zeitschritt ein: Die {1} sind alle gleich hoch, die {2} liegen auf einer {3}. Ziehe den {4}, um den Bestand zu einem beliebigen Zeitpunkt abzulesen.": "Nastav: {0} a přírůstek za časový krok. Všechny {1} jsou stejně vysoké a {2} leží na {3}. Táhni {4} a odečti množství v libovolném okamžiku.",
"Stelle {0} und Prozentsatz ein: Jede der {1} ist um denselben Faktor höher als die vorige, die {2} wird immer steiler. Die {3} ist überall gleich lang. Ziehe den {4}.": "Nastav: {0} a procento. Další {1} jsou pokaždé vyšší stejným činitelem a {2} je čím dál strmější. Všude stejně dlouhá je {3}. Táhni {4}.",
"Stelle {0}, {1} und Anteil k ein: Jede der {2} schliesst denselben Anteil der Lücke bis zur Schranke. Die {3} wird immer flacher und kommt der Schranke beliebig nahe. Ziehe den {4}.": "Nastav: {0}, {1} a podíl k. Další {2} uzavřou pokaždé stejný díl mezery k mezi. Čára ({3}) je čím dál plošší a blíží se k mezi libovolně blízko. Táhni {4}.",
"Stelle {0}, {1} und Wachstumskonstante ein: Die {2} wächst zuerst fast exponentiell, am {3} bei halber Schranke am schnellsten und nähert sich dann der Schranke. Ziehe den {4}.": "Nastav: {0}, {1} a růstová konstanta. Čára ({2}) roste nejprve téměř exponenciálně, nejrychleji v {3}, v polovině meze, a pak se blíží k mezi. Táhni {4}.",
"Alle Modelle starten beim selben {0}: {1} und {2}. Verstelle die Regler, bis ein Modell die {3} trifft; die {4} zeigt, welches am besten passt.": "Všechny modely začínají ve stejném bodě ({0}): {1} a {2}. Posouvej posuvníky, dokud některý model nezasáhne {3}; {4} ukáže, který sedí nejlépe.",
