"Die Punkte liegen auf einer Geraden mit der Steigung {0} und dem Anfangswert {1}": "Body leží na přímce se směrnicí {0} a počáteční hodnotou {1}",
"<0>Wert zu einem beliebigen Zeitpunkt:</0> {1} in die Formel einsetzen.": "<0>Hodnota v libovolném okamžiku:</0> dosaď {1} do vzorce.",
"<0>Werte:</0> {1} in die Formel einsetzen.": "<0>Hodnoty:</0> dosaď {1} do vzorce.",
"<0>Schritt für Schritt:</0> Jeder Wert entsteht aus dem vorigen durch Addieren von {1}.": "<0>Krok za krokem:</0> každá hodnota vznikne z předchozí přičtením {1}.",
"<0>Schritt für Schritt:</0> Jeder Wert entsteht aus dem vorigen durch Multiplizieren mit {1}.": "<0>Krok za krokem:</0> každá hodnota vznikne z předchozí vynásobením {1}.",
"<0>Lineares Wachstum:</0> In gleichen Zeitschritten ändert sich der Bestand immer um denselben Betrag {1}. Für {2} nimmt er ab.": "<0>Lineární růst:</0> ve stejných časových krocích se množství mění vždy o stejnou hodnotu {1}. Pro {2} klesá.",
"<0>Aufgebraucht:</0> Der Bestand ist {1}, wenn {2} gilt.": "<0>Vyčerpáno:</0> množství je {1}, když platí {2}.",
"Der Bestand wächst pro Zeitschritt um {0} und verdoppelt sich alle {1} Zeitschritte": "Množství roste o {0} za časový krok a zdvojnásobí se každých {1} časových kroků",
"Der Bestand nimmt pro Zeitschritt um {0} ab und halbiert sich alle {1} Zeitschritte": "Množství klesá o {0} za časový krok a zmenší se na polovinu každých {1} časových kroků",
"Der Bestand bleibt bei {0}": "Množství zůstává {0}",
"Für {0} ist {1}: Der Bestand bleibt konstant.": "Pro {0} je {1}: množství zůstává stejné.",
"<0>Verdopplungszeit:</0> Sie hängt nur vom Faktor {1} ab, nicht vom Anfangswert.": "<0>Doba zdvojení:</0> závisí jen na činiteli {1}, ne na počáteční hodnotě.",
"<0>Halbwertszeit:</0> Sie hängt nur vom Faktor {1} ab, nicht vom Anfangswert.": "<0>Poločas:</0> závisí jen na činiteli {1}, ne na počáteční hodnotě.",
"<0>Exponentielles Wachstum:</0> In gleichen Zeitschritten wird der Bestand immer mit demselben Faktor {1} multipliziert. Der Zuwachs ist darum proportional zum Bestand.": "<0>Exponenciální růst:</0> ve stejných časových krocích se množství násobí vždy stejným činitelem {1}. Přírůstek je proto úměrný množství.",
"Der Bestand nähert sich der Schranke {0} von unten, ohne sie zu erreichen": "Množství se blíží k mezi {0} zdola, aniž jí dosáhne",
"Der Bestand nähert sich der Schranke {0} von oben, ohne sie zu erreichen": "Množství se blíží k mezi {0} shora, aniž jí dosáhne",
"<0>Halbwertszeit des Abstands:</0> Nach dieser Zeit ist der Abstand zur Schranke jeweils nur noch halb so gross.": "<0>Poločas vzdálenosti:</0> po této době je vzdálenost od meze pokaždé jen poloviční.",
"<0>Abstand zur Schranke:</0> Er schrumpft in jedem Schritt mit dem Faktor {1}, also exponentiell.": "<0>Vzdálenost od meze:</0> v každém kroku se zmenší činitelem {1}, tedy exponenciálně.",
"<0>Beschränktes Wachstum:</0> Der Bestand nähert sich einer Schranke {1}. In jedem Zeitschritt kommt derselbe Anteil {2} des Abstands zur Schranke dazu.": "<0>Omezený růst:</0> množství se blíží k mezi {1}. V každém časovém kroku přibude stejný díl {2} vzdálenosti od meze.",
"Der Anfangswert liegt genau auf der Schranke: Der Bestand ändert sich nicht.": "Počáteční hodnota leží přesně na mezi: množství se nemění.",
"S-förmige Kurve von {0} zur Schranke {1}": "Křivka ve tvaru S od {0} k mezi {1}",
"<0>Wendepunkt:</0> Am schnellsten wächst der Bestand, wenn er die halbe Schranke erreicht. Danach wird die Kurve wieder flacher.": "<0>Inflexní bod:</0> množství roste nejrychleji, když dosáhne poloviny meze. Potom je křivka opět plošší.",
"<0>Logistisches Wachstum:</0> Anfangs wächst der Bestand fast exponentiell, dann bremst die Schranke {1}. Die Änderungsrate ist proportional zum Bestand und zum noch freien Anteil.": "<0>Logistický růst:</0> zpočátku množství roste téměř exponenciálně, pak ho brzdí mez {1}. Rychlost změny je úměrná množství a dosud volnému podílu.",
"Der Anfangswert liegt über der Schranke: Der Bestand nimmt ab und nähert sich {0} von oben.": "Počáteční hodnota leží nad mezí: množství klesá a blíží se k {0} shora.",
"Der Anfangswert liegt schon über der halben Schranke: Das Wachstum wird von Anfang an langsamer.": "Počáteční hodnota leží už nad polovinou meze: růst se od začátku zpomaluje.",
"Mit diesen Einstellungen passt das Modell «logistisch» am besten": "S tímto nastavením sedí nejlépe model „logistický“",
"Mit diesen Einstellungen passt das Modell «exponentiell» am besten": "S tímto nastavením sedí nejlépe model „exponenciální“",
"Mit diesen Einstellungen passt das Modell «beschränkt» am besten": "S tímto nastavením sedí nejlépe model „omezený“",
"Mit diesen Einstellungen passt das Modell «linear» am besten": "S tímto nastavením sedí nejlépe model „lineární“",
"<0>Abweichung von den Daten:</0> Für jedes Modell wird der mittlere Abstand zwischen Messwert und Modellwert berechnet. Je kleiner, desto besser passt das Modell.": "<0>Odchylka od dat:</0> pro každý model se spočítá průměrná vzdálenost mezi naměřenou hodnotou a hodnotou modelu. Čím je menší, tím lépe model sedí.",
"<0>Werte im Vergleich:</0> am Anfang, in der Mitte und am Ende des Zeitraums.": "<0>Porovnání hodnot:</0> na začátku, uprostřed a na konci období.",
"<0>Woran man sie unterscheidet:</0> linear: gleiche Differenzen in gleichen Zeitschritten; exponentiell: gleiche Quotienten; beschränkt: der Abstand zur Schranke hat gleiche Quotienten; logistisch: S-förmig, erst fast exponentiell, dann beschränkt.": "<0>Jak je rozlišit:</0> lineární: stejné rozdíly ve stejných časových krocích; exponenciální: stejné podíly; omezený: vzdálenost od meze má stejné podíly; logistický: ve tvaru S, nejprve téměř exponenciální, pak omezený.",
"Schalte links mindestens ein Modell ein.": "Zapni vlevo alespoň jeden model.",
