"Amortisation": "Návratnost",
"Zwei Investitionen vergleichen": "Porovnání dvou investic",
"Kapitalwert mit abgezinsten Zahlungen am Zeitstrahl, interner Zinssatz als Nullstelle der Kapitalwertkurve, statische und dynamische Amortisation, Annuität, Vergleich zweier Investitionen": "Čistá současná hodnota s diskontovanými platbami na časové ose, vnitřní výnosové procento jako nulový bod křivky, statická a dynamická doba návratnosti, anuita, porovnání dvou investic",
"Lohnt sich eine Investition? Zahlungen am Zeitstrahl abzinsen, den Kapitalwert und den internen Zinssatz bestimmen, die Amortisationszeit ablesen und zwei Investitionen vergleichen.": "Vyplatí se investice? Diskontování plateb na časové ose, čistá současná hodnota a vnitřní výnosové procento, odečtení doby návratnosti a porovnání dvou investic.",
"{0} Trage links die Investition und die Rückflüsse der einzelnen Jahre ein. Der Kalkulationszinssatz lässt sich im Bild ziehen.": "{0} Zadej vlevo investici a příjmy jednotlivých let. Diskontní sazbu lze táhnout přímo v obrázku.",
"Der interne Zinssatz wird zwischen {0} % und {1} % gesucht. Wechseln die Zahlungen mehrmals das Vorzeichen, kann es mehrere geben; gezeigt wird der kleinste.": "Vnitřní výnosové procento se hledá mezi {0} % a {1} %. Mění-li platby znaménko vícekrát, může jich být několik; zobrazí se nejmenší.",
"Die Ansichten «Kapitalwert», «Interner Zinssatz» und «Amortisation» zeigen dieselbe Investition; Änderungen gelten in allen dreien.": "Pohledy „Čistá současná hodnota“, „Vnitřní výnosové procento“ a „Doba návratnosti“ ukazují tutéž investici; změny platí ve všech třech.",
"Die Investition wird heute bezahlt (Zeitpunkt {0}), jeder Rückfluss am Ende seines Jahres. Ein negativer Rückfluss ist eine weitere Auszahlung.": "Investice se platí dnes (okamžik {0}), každý příjem na konci svého roku. Záporný příjem je další výdaj.",
"Kapitalwertmethode: Geld, das später fliesst, ist heute weniger wert, weil man es in der Zwischenzeit zum Kalkulationszinssatz anlegen könnte. Darum werden alle Zahlungen auf den Zeitpunkt der Investition abgezinst und erst dann zusammengezählt.": "Metoda čisté současné hodnoty: peníze, které přijdou později, mají dnes menší hodnotu, protože by je mezitím šlo uložit za diskontní sazbu. Proto se všechny platby diskontují k okamžiku investice a teprve pak sečtou.",
"Der interne Zinssatz ist die Verzinsung, die eine Investition selbst erbringt. Man findet ihn durch Probieren und Interpolieren, weil sich die Gleichung meist nicht nach dem Zinssatz auflösen lässt.": "Vnitřní výnosové procento je zúročení, které investice sama přináší. Hledá se zkoušením a interpolací, protože rovnici většinou nelze podle sazby vyřešit.",
"Die Amortisationszeit (Payback) sagt, wie lange das Kapital gebunden ist, und damit etwas über das Risiko. Über den Gewinn sagt sie nichts, denn Zahlungen nach der Amortisation werden nicht beachtet.": "Doba návratnosti říká, jak dlouho je kapitál vázán, a tím něco o riziku. O zisku neříká nic, protože platby po návratu se neberou v úvahu.",
"Kapitalwert und interner Zinssatz können verschiedene Rangfolgen liefern: Späte, grosse Rückflüsse leiden stärker unter einem hohen Zinssatz als frühe. Massgebend ist der Kapitalwert beim eigenen Kalkulationszinssatz.": "Čistá současná hodnota a vnitřní výnosové procento mohou dát různé pořadí: pozdní velké příjmy trpí vysokou sazbou víc než časné. Rozhoduje čistá současná hodnota při vlastní diskontní sazbě.",
