"Trage links die {0} und die {1} ein: Jede Zahlung wird mit dem Kalkulationszinssatz zu ihrem {2} abgezinst. Die Summe aller Barwerte ist der {3}; ist er positiv, lohnt sich die Investition.": "Zadej vlevo dvě věci ({0} a {1}): každá platba se diskontní sazbou přepočítá na dnešek ({2}). Součet všech současných hodnot je {3}; je-li kladná, investice se vyplatí.",
"Ziehe den {0} entlang der {1}: Je höher der Zinssatz, desto kleiner der Kapitalwert. Beim {2} ist der Kapitalwert genau null; liegt er über dem Kalkulationszinssatz, lohnt sich die Investition.": "Táhni bod ({0}) po křivce ({1}): čím vyšší sazba, tím menší čistá současná hodnota. V jednom místě ({2}) je čistá současná hodnota přesně nula; leží-li nad diskontní sazbou, investice se vyplatí.",
"Die {0} summiert die Zahlungen ohne Zins, die {1} die abgezinsten Zahlungen. Wo eine Linie die Nulllinie kreuzt, ist die Investition zurückgeflossen: nach der {2} und nach der {3}.": "Jedna čára ({0}) sčítá platby bez úroku, druhá ({1}) diskontované platby. Kde čára protne nulovou čáru, investice se vrátila: doba návratnosti je dvojí ({2} a {3}).",
"Vergleiche {0} und {1}: Ziehe den {2} und lies ab, welche den grösseren Kapitalwert hat. Am {3} sind beide gleich gut; links und rechts davon ist jeweils eine andere besser.": "Porovnej obě možnosti ({0} a {1}): táhni bod ({2}) a odečti, která má větší čistou současnou hodnotu. V jednom místě ({3}) jsou obě stejně dobré; vlevo a vpravo od něj je pokaždé lepší jiná.",
