"<0>Annuität:</0> der Kapitalwert, umgerechnet in einen gleich hohen Betrag am Ende jedes Jahres.": "<0>Anuita:</0> čistá současná hodnota přepočtená na stejnou částku na konci každého roku.",
"<0>Entscheid:</0> Ein positiver Kapitalwert heisst, dass die Investition mehr einbringt als eine Anlage zum Kalkulationszinssatz.": "<0>Rozhodnutí:</0> kladná čistá současná hodnota znamená, že investice vynese víc než uložení za diskontní sazbu.",
"<0>Kapitalwert:</0> die Summe aller Barwerte, vermindert um die Investition.": "<0>Čistá současná hodnota:</0> součet všech současných hodnot zmenšený o investici.",
"<0>Abzinsen:</0> Geld, das erst in {1} Jahren fliesst, ist heute weniger wert. Jede Zahlung wird darum durch {2} geteilt, mit dem Zinsfaktor {3}.": "<0>Diskontování:</0> peníze, které přijdou až za {1} let, mají dnes menší hodnotu. Každá platba se proto vydělí {2}, s úrokovým činitelem {3}.",
"Interner Zinssatz {0}: Die Investition lohnt sich nicht bei einem Kalkulationszinssatz von {1}": "Vnitřní výnosové procento {0}: při diskontní sazbě {1} se investice nevyplatí",
"Interner Zinssatz {0}: Die Investition lohnt sich bei einem Kalkulationszinssatz von {1}": "Vnitřní výnosové procento {0}: při diskontní sazbě {1} se investice vyplatí",
"<0>Entscheid:</0> Liegt der interne Zinssatz über dem Kalkulationszinssatz, lohnt sich die Investition.": "<0>Rozhodnutí:</0> je-li vnitřní výnosové procento vyšší než diskontní sazba, investice se vyplatí.",
"Genauer Wert (mit weiteren Schritten): {0}.": "Přesnější hodnota (po dalších krocích): {0}.",
"<0>Linear interpolieren:</0> Zwischen den beiden Punkten wird die Kurve durch eine Gerade ersetzt.": "<0>Lineární interpolace:</0> mezi oběma body se křivka nahradí přímkou.",
"<0>Probieren:</0> Die Gleichung lässt sich meist nicht nach {1} auflösen. Man sucht zwei Zinssätze, zwischen denen der Kapitalwert das Vorzeichen wechselt.": "<0>Zkoušení:</0> rovnici většinou nelze vyřešit podle {1}. Hledají se dvě sazby, mezi nimiž čistá současná hodnota mění znaménko.",
"<0>Interner Zinssatz:</0> der Zinssatz, bei dem der Kapitalwert genau {1} ist. Er gibt an, zu wie viel Prozent sich das eingesetzte Kapital verzinst.": "<0>Vnitřní výnosové procento:</0> sazba, při které je čistá současná hodnota přesně {1}. Udává, kolika procenty se vložený kapitál zúročí.",
"Der Kapitalwert ist bei jedem Zinssatz negativ": "Čistá současná hodnota je při každé sazbě záporná",
"Der Kapitalwert ist bei jedem Zinssatz positiv": "Čistá současná hodnota je při každé sazbě kladná",
