"Zwischen {0} und {1} wechselt der Kapitalwert sein Vorzeichen nicht: Es gibt dort keinen internen Zinssatz.": "Mezi {0} a {1} čistá současná hodnota znaménko nemění: žádné vnitřní výnosové procento tam není.",
