"Die Amortisationszeit misst das Risiko, nicht den Gewinn: Zahlungen nach diesem Zeitpunkt werden nicht beachtet.": "Doba návratnosti měří riziko, ne zisk: pozdější platby se neberou v úvahu.",
"<0>Dynamisch:</0> Dasselbe mit den abgezinsten Zahlungen. Spätere Rückflüsse zählen weniger, darum dauert die Amortisation länger.": "<0>Dynamicky:</0> totéž s diskontovanými platbami. Pozdější příjmy se počítají méně, proto návrat trvá déle.",
"Im Jahr des Vorzeichenwechsels wird ein gleichmässiger Zufluss angenommen:": "V roce změny znaménka se předpokládá rovnoměrný příjem:",
"<0>Statisch:</0> Die Zahlungen werden ohne Zins aufsummiert, bis die Investition zurückgeflossen ist.": "<0>Staticky:</0> platby se sčítají bez úroku, dokud se investice nevrátí.",
"Mit Zins gerechnet fliesst die Investition in der Laufzeit nicht zurück.": "Počítáno s úrokem se investice během doby trvání nevrátí.",
"Die Rückflüsse decken die Investition nicht.": "Příjmy investici nepokryjí.",
"Bei {0} ist Investition A besser": "Při {0} je lepší investice A",
"Bei {0} ist Investition B besser": "Při {0} je lepší investice B",
"Bei {0} lohnt sich keine der beiden Investitionen": "Při {0} se nevyplatí žádná z obou investic",
"Bei {0} sind beide Investitionen gleich gut": "Při {0} jsou obě investice stejně dobré",
"<0>Entscheid:</0> Gewählt wird die Investition mit dem grösseren Kapitalwert, sofern er positiv ist.": "<0>Rozhodnutí:</0> volí se investice s větší čistou současnou hodnotou, pokud je kladná.",
"Kapitalwert und interner Zinssatz führen hier zu verschiedenen Rangfolgen. Massgebend ist der Kapitalwert beim eigenen Kalkulationszinssatz.": "Čistá současná hodnota a vnitřní výnosové procento zde vedou k různému pořadí. Rozhoduje čistá současná hodnota při vlastní diskontní sazbě.",
"<0>Gleichstand:</0> Bei diesem Zinssatz haben beide Investitionen denselben Kapitalwert. Darunter ist die eine besser, darüber die andere.": "<0>Rovnost:</0> při této sazbě mají obě investice stejnou čistou současnou hodnotu. Pod ní je lepší jedna, nad ní druhá.",
"Interne Zinssätze:": "Vnitřní výnosová procenta:",
"Kapitalwerte beim Kalkulationszinssatz": "Čisté současné hodnoty při diskontní sazbě",
"Aussagenlogik": "Výroková logika",
"∧ Aussagenlogik": "∧ Výroková logika",
"Verknüpfungen": "Logické spojky",
"Wahrheitstafel einer Aussage": "Pravdivostní tabulka výroku",
"Gleichwertige Aussagen und Gesetze": "Ekvivalentní výroky a zákony",
"Implikation, Umkehrung, Kontraposition": "Implikace, obrácená, obměněná",
"Verknüpfungen (nicht, und, oder, entweder–oder, wenn–dann, genau dann wenn) mit Wahrheitstafel und Mengenbild, Wahrheitstafel beliebiger Aussagen, Tautologie und Widerspruch, gleichwertige Aussagen und Gesetze, Implikation mit Umkehrung und Kontraposition": "Logické spojky (ne, a, nebo, buď–anebo, jestliže–pak, právě když) s pravdivostní tabulkou a Vennovým diagramem, pravdivostní tabulka libovolného výroku, tautologie a kontradikce, ekvivalentní výroky a zákony, implikace s obrácenou a obměněnou",
"Aussagen verknüpfen und auswerten: Wahrheitstafeln Schritt für Schritt, das passende Mengenbild dazu, die wichtigsten Gesetze zum Umformen und der Unterschied zwischen einer Implikation und ihrer Umkehrung.": "Spojování a vyhodnocování výroků: pravdivostní tabulky krok za krokem, odpovídající Vennův diagram, nejdůležitější zákony pro úpravy a rozdíl mezi implikací a obrácenou implikací.",
"{0} Klicke eine Zeile der Wahrheitstafel an oder tippe links eine eigene Aussage ein. Das Mengenbild zeigt, wo sie wahr ist.": "{0} Klikni na řádek pravdivostní tabulky nebo vlevo zapiš vlastní výrok. Vennův diagram ukáže, kde je pravdivý.",
"Aussagen tippst du mit den Knöpfen unter dem Feld oder über die Tastatur: ! für nicht, & für und, | für oder, ^ für entweder–oder; die Pfeile als Minus- und Grösser-Zeichen. Auch die Wörter nicht, und, oder werden verstanden.": "Výroky zapisuješ tlačítky pod polem nebo z klávesnice: ! pro ne, & pro a, | pro nebo, ^ pro buď–anebo; šipky znaménky minus a větší než. Rozumí se i slovům not, and, or.",
"Ohne Klammern gilt: zuerst nicht, dann und, dann oder, dann wenn–dann, zuletzt genau dann wenn. Erlaubt sind bis zu vier Variablen; ein Mengenbild gibt es bei zwei oder drei.": "Bez závorek platí pořadí: nejprve ne, pak a, pak nebo, pak jestliže–pak, nakonec právě když. Povoleny jsou nejvýše čtyři proměnné; Vennův diagram se zobrazí pro dvě nebo tři.",
"Die Wahrheitswerte stehen als w und f oder als {0} und {1}; die Wahl gilt für alle Ansichten.": "Pravdivostní hodnoty se píší jako w a f (pravda, nepravda) nebo jako {0} a {1}; volba platí pro všechny pohledy.",
"Eine Aussage ist entweder wahr oder falsch. Verknüpfungen bilden aus Aussagen neue Aussagen; die Wahrheitstafel legt für jede Kombination der Wahrheitswerte fest, ob die neue Aussage wahr ist. Im Mengenbild bedeutet «im Kreis A»: A ist wahr.": "Výrok je buď pravdivý, nebo nepravdivý. Spojky tvoří z výroků nové výroky; pravdivostní tabulka určuje pro každou kombinaci pravdivostních hodnot, zda je nový výrok pravdivý. Ve Vennově diagramu znamená „v kruhu A“: A je pravdivý.",
"Bei n Variablen hat die Wahrheitstafel {0}ⁿ Zeilen. Man rechnet von innen nach aussen: zuerst Klammern und Verneinungen, dann «und», dann «oder», zuletzt die Pfeile. Eine Tautologie ist immer wahr, ein Widerspruch immer falsch.": "Při n proměnných má pravdivostní tabulka {0}ⁿ řádků. Počítá se zevnitř ven: nejprve závorky a negace, pak „a“, pak „nebo“, nakonec šipky. Tautologie je vždy pravdivá, kontradikce vždy nepravdivá.",
"Zwei Aussagen sind gleichwertig (äquivalent), wenn sie bei jeder Belegung denselben Wahrheitswert haben. Wichtige Gesetze: De Morgan, Distributivgesetze, doppelte Verneinung, Kontraposition. Mit ihnen formt man Aussagen um wie Terme in der Algebra.": "Dva výroky jsou ekvivalentní, mají-li při každém ohodnocení stejnou pravdivostní hodnotu. Důležité zákony: De Morganovy, distributivní, dvojí negace, obměna implikace. Pomocí nich se výroky upravují jako výrazy v algebře.",
"Aus «wenn A, dann B» folgt nicht «wenn B, dann A». Gleichwertig ist nur die Kontraposition «wenn nicht B, dann nicht A»; darauf beruht der indirekte Beweis. A heisst hinreichend für B, B notwendig für A.": "Z „jestliže A, pak B“ neplyne „jestliže B, pak A“. Ekvivalentní je jen obměněná implikace „jestliže ne B, pak ne A“; na ní stojí nepřímý důkaz. A se nazývá postačující podmínka pro B, B nutná podmínka pro A.",
"logische Verknüpfung": "logická spojka",
