"Wähle links eine {0} und klicke eine Zeile der {1} an: Die {2} gehört zu einem Feld im {3}. Schraffiert sind die Felder, in denen die verknüpfte Aussage wahr ist.": "Zvol vlevo operaci ({0}) a klikni na řádek tabulky ({1}): {2} patří k jednomu poli obrázku ({3}). Vyšrafována jsou pole, ve kterých je složený výrok pravdivý.",
"Tippe links eine {0} ein: Die {1} rechnet sie für alle Belegungen aus, von den {2} bis zur {3}. Steht dort überall «wahr», ist die Aussage eine Tautologie.": "Zapiš vlevo {0}: tabulka ({1}) ho vyhodnotí pro všechna ohodnocení, krok za krokem ({2}) až do konce ({3}). Je-li tam všude „pravda“, je výrok tautologií.",
"Vergleiche die {0} und die {1}: Stimmen ihre Spalten in der {2} überall überein, sind sie gleichwertig; dann sind auch die {3} gleich schraffiert. Unter «Beispiel wählen …» stehen die wichtigsten Gesetze.": "Porovnej oba výroky ({0} a {1}): shodují-li se jejich sloupce v tabulce ({2}) všude, jsou ekvivalentní; pak jsou stejně vyšrafovány i obrázky ({3}). Nejdůležitější zákony najdeš pod „Vyberte příklad …“.",
"Wähle ein Beispiel und klicke eine {0} an: Die {1} ist nur falsch, wenn A wahr und B falsch ist. Die {2} hat dieselben Wahrheitswerte und ist gleichwertig, die {3} nicht. Die {4} ist genau dann wahr, wenn die Implikation falsch ist.": "Zvol příklad a klikni na sloupec ({0}): první výrok ({1}) je nepravdivý jen tehdy, když A platí a B neplatí. Třetí ({2}) má stejné pravdivostní hodnoty a je ekvivalentní, druhý ({3}) ne. Poslední ({4}) je pravdivý právě tehdy, když je implikace nepravdivá.",
