"<0>Mengenbild:</0> Im Kreis A ist die Aussage A wahr, ausserhalb ist sie falsch. Schraffiert sind die Felder, in denen die verknüpfte Aussage wahr ist.": "<0>Vennův diagram:</0> v kruhu A je výrok A pravdivý, mimo něj nepravdivý. Vyšrafována jsou pole, ve kterých je složený výrok pravdivý.",
"<0>Negation (nicht):</0> Die Negation kehrt den Wahrheitswert um: Aus wahr wird falsch, aus falsch wird wahr.": "<0>Negace (ne):</0> negace obrací pravdivostní hodnotu: z pravdy se stane nepravda, z nepravdy pravda.",
"Gelesen «nicht A». Beispiel: A «Es regnet.» wird zu «Es regnet nicht.»": "Čteme „ne A“. Příklad: A „Prší.“ se změní na „Neprší.“",
"<0>Konjunktion (und):</0> Die Konjunktion ist nur wahr, wenn beide Aussagen wahr sind.": "<0>Konjunkce (a):</0> konjunkce je pravdivá jen tehdy, když jsou pravdivé oba výroky.",
"Gelesen «A und B». Beispiel: «Es regnet, und es ist kalt.»": "Čteme „A a B“. Příklad: „Prší a je zima.“",
"<0>Disjunktion (oder):</0> Die Disjunktion ist wahr, wenn mindestens eine der beiden Aussagen wahr ist. Auch beide dürfen wahr sein (einschliessendes Oder).": "<0>Disjunkce (nebo):</0> disjunkce je pravdivá, když je pravdivý alespoň jeden z obou výroků. Pravdivé mohou být i oba (nevylučovací nebo).",
"Gelesen «A oder B». Beispiel: «Zum Kaffee nehme ich Milch oder Zucker» schliesst beides zusammen nicht aus.": "Čteme „A nebo B“. Příklad: „Do kávy si dám mléko nebo cukr“ nevylučuje obojí zároveň.",
"<0>Entweder – oder:</0> Das ausschliessende Oder ist wahr, wenn genau eine der beiden Aussagen wahr ist.": "<0>Buď – anebo:</0> vylučovací nebo je pravdivé, když je pravdivý právě jeden z obou výroků.",
"Gelesen «entweder A oder B». Beispiel: «Ich fahre entweder mit dem Zug oder mit dem Auto.»": "Čteme „buď A, anebo B“. Příklad: „Pojedu buď vlakem, anebo autem.“",
"<0>Implikation (wenn – dann):</0> Die Implikation ist nur falsch, wenn A wahr und B falsch ist. Ist A falsch, gilt sie als wahr.": "<0>Implikace (jestliže – pak):</0> implikace je nepravdivá jen tehdy, když A platí a B neplatí. Neplatí-li A, považuje se za pravdivou.",
"Gelesen «wenn A, dann B». Beispiel: «Wenn es regnet, ist die Strasse nass.» Bei trockenem Wetter ist dieses Versprechen nicht gebrochen.": "Čteme „jestliže A, pak B“. Příklad: „Jestliže prší, je silnice mokrá.“ Za sucha tento slib porušen není.",
"<0>Äquivalenz (genau dann, wenn):</0> Die Äquivalenz ist wahr, wenn beide Aussagen denselben Wahrheitswert haben.": "<0>Ekvivalence (právě když):</0> ekvivalence je pravdivá, když mají oba výroky stejnou pravdivostní hodnotu.",
"Gelesen «A genau dann, wenn B». Beispiel: «Eine Zahl ist genau dann gerade, wenn ihre letzte Ziffer gerade ist.»": "Čteme „A právě tehdy, když B“. Příklad: „Číslo je sudé právě tehdy, když je sudá jeho poslední číslice.“",
"Zeilen": "Řádky",
"<0>Belegungen:</0> Bei {1} Variablen gibt es {2} Zeilen, weil jede Variable wahr oder falsch sein kann.": "<0>Ohodnocení:</0> při {1} proměnných je {2} řádků, protože každá proměnná může být pravdivá, nebo nepravdivá.",
"<0>Reihenfolge:</0> Man rechnet von innen nach aussen, jede Teilaussage in einer eigenen Spalte.": "<0>Pořadí:</0> počítá se zevnitř ven, každý dílčí výrok ve vlastním sloupci.",
"<0>Auswertung:</0> Die letzte Spalte zeigt, für welche Belegungen die Aussage wahr ist.": "<0>Vyhodnocení:</0> poslední sloupec ukazuje, při kterých ohodnoceních je výrok pravdivý.",
"Die Aussage ist in {0} von {1} Zeilen wahr: erfüllbar, aber keine Tautologie": "Výrok je pravdivý v {0} z {1} řádků: splnitelný, ale ne tautologie",
"Die Aussage ist in allen {0} Zeilen wahr: eine Tautologie": "Výrok je pravdivý ve všech řádcích ({0}): tautologie",
"Die Aussage ist in keiner Zeile wahr: ein Widerspruch": "Výrok není pravdivý v žádném řádku: kontradikce",
"Tautologie: in jeder Zeile wahr": "Tautologie: pravdivý v každém řádku",
"Widerspruch: in keiner Zeile wahr": "Kontradikce: pravdivý v žádném řádku",
"Erfüllbar, aber nicht immer wahr": "Splnitelný, ale ne vždy pravdivý",
