"Zweite Aussage (grün)": "Druhý výrok (zelený)",
"<0>Gleichwertig</0> heissen zwei Aussagen, wenn sie bei jeder Belegung denselben Wahrheitswert haben. Man vergleicht ihre Spalten in der Wahrheitstafel Zeile für Zeile.": "Dva výroky se nazývají <0>ekvivalentní</0>, mají-li při každém ohodnocení stejnou pravdivostní hodnotu. Jejich sloupce v pravdivostní tabulce se porovnávají řádek po řádku.",
"<0>Vergleich:</0> In allen {1} Zeilen stimmen die beiden Spalten überein. Im Mengenbild sind dieselben Felder schraffiert.": "<0>Porovnání:</0> oba sloupce se shodují ve všech řádcích ({1}). Ve Vennově diagramu jsou vyšrafována stejná pole.",
"<0>Unterschied:</0> Bei diesen Belegungen haben die beiden Aussagen verschiedene Wahrheitswerte.": "<0>Rozdíl:</0> při těchto ohodnoceních mají oba výroky různé pravdivostní hodnoty.",
"Gleichwertige Aussagen darf man gegeneinander austauschen, so wie man in der Algebra Terme umformt.": "Ekvivalentní výroky lze navzájem zaměňovat, stejně jako se v algebře upravují výrazy.",
"Die Aussagen sind gleichwertig": "Výroky jsou ekvivalentní",
