"Die {0} erklärt nur einen Teil der Streuung der y-Werte: Der {1} ist das Bestimmtheitsmass r². Unten sind die {2} einzeln aufgetragen. Liegen sie ohne Muster um die {3}, passt eine Gerade; bilden sie einen Bogen, wäre eine Kurve besser.": "Modrá přímka ({0}) vysvětluje jen část variability hodnot y: mírou je koeficient determinace r² ({1}). Dole jsou zvlášť vyneseny odchylky od přímky ({2}). Leží-li bez vzoru kolem vodorovné čáry ({3}), přímka vyhovuje; tvoří-li oblouk, byla by lepší křivka.",
