"gestrichelte Parallelogramm": "rovnoběžník",
"Ziehe die Spitzen der Vektoren {0} und {1}: Hängt man den zweiten Pfeil an die Spitze des ersten, zeigt der {2} vom Anfang zum Ende. Das {3} zeigt, dass die Reihenfolge keine Rolle spielt. Wähle links Summe, Differenz oder Linearkombination.": "Táhni za hroty vektorů {0} a {1}: připojí-li se druhá šipka ke hrotu první, výsledek ({2}) vede od začátku do konce. Čárkované čáry ({3}) ukazují, že na pořadí nezáleží. Vlevo zvol součet, rozdíl nebo lineární kombinaci.",
"Zwischenwinkel φ": "úhel φ mezi vektory",
"orange Schatten von b auf a": "stín b na a",
"Ziehe die Spitzen der Vektoren {0} und {1}: Das Skalarprodukt ist positiv bei spitzem, null bei rechtem und negativ bei stumpfem {2}. Der {3} zeigt, welcher Teil von b in Richtung von a wirkt.": "Táhni za hroty vektorů {0} a {1}: skalární součin je kladný, nulový nebo záporný podle toho, zda je úhel ({2}) ostrý, pravý nebo tupý. Oranžová úsečka ({3}) ukazuje, jaká část b působí ve směru a.",
"blaue Gerade g": "modrá přímka g",
"Stützpunkt A": "výchozí bod A",
"Richtungsvektor v": "směrový vektor v",
"Punkt P auf der Geraden": "bod P na přímce",
"Normalenvektor n": "normálový vektor n",
"Die {0} ist durch den {1} und den {2} festgelegt. Ziehe den {3} oder stelle links den Parameter t ein: Bei t = {4} liegt P an der Spitze von v, bei t = {5} doppelt so weit. Der {6} steht senkrecht auf der Geraden und liefert die Koordinatengleichung.": "Přímku ({0}) určují bod ({1}) a vektor ({2}). Táhni za fialový bod ({3}) nebo vlevo nastav parametr t: pro t = {4} leží P na hrotu v, pro t = {5} dvakrát dál. Oranžová šipka ({6}) je kolmá k přímce a dává obecnou rovnici.",
"Punkt P neben der Geraden": "bod P vedle přímky",
"Geraden durch A": "přímka procházející bodem A",
"Länge des roten Lots": "délka kolmice",
