"Ziehe den {0}: Der kürzeste Weg zur {1} steht senkrecht auf ihr und endet im {2}. Die {3} ist der Abstand. Auch den {4} und die Spitze des Richtungsvektors kannst du ziehen.": "Táhni za fialový bod ({0}): nejkratší cesta k přímce ({1}) je k ní kolmá a končí v oranžovém bodě ({2}). Červená úsečka ({3}) je vzdálenost. Táhnout lze i za bod A ({4}) a za hrot směrového vektoru.",
