"Spitzer Winkel: Das Skalarprodukt ist positiv.": "Ostrý úhel: skalární součin je kladný.",
"Rechter Winkel: Das Skalarprodukt ist null.": "Pravý úhel: skalární součin je nulový.",
"Stumpfer Winkel: Das Skalarprodukt ist negativ.": "Tupý úhel: skalární součin je záporný.",
"Ein Nullvektor hat keine Richtung.": "Nulový vektor nemá směr.",
"Vektor und Betrag": "Vektor a velikost",
"Rechnen mit Vektoren": "Počítání s vektory",
