"Division ohne Rest": "Dělení beze zbytku",
"Fehlende Potenzen im Zähler": "Chybějící mocniny v čitateli",
"Nenner vom Grad zwei": "Jmenovatel druhého stupně",
"Leitkoeffizient im Nenner": "Vedoucí koeficient ve jmenovateli",
"Nullstelle, Polstelle und hebbare Lücke": "Nulový bod, pól a odstranitelná nespojitost",
"Zwei Polstellen und eine Nullstelle": "Dva póly a jeden nulový bod",
"Doppelte Nullstelle: kein Vorzeichenwechsel": "Dvojnásobný nulový bod: beze změny znaménka",
"Doppelte Polstelle: kein Vorzeichenwechsel": "Dvojnásobný pól: beze změny znaménka",
"Überall positiv": "Všude kladná",
"Die x-Achse ist waagrechte Asymptote.": "Osa x je vodorovnou asymptotou.",
"Waagrechte Asymptote {0}": "Vodorovná asymptota {0}",
"Schiefe Asymptote {0}": "Šikmá asymptota {0}",
"Näherungskurve {0}": "Asymptotická křivka {0}",
"Ganzrationale Funktion: keine Asymptote": "Polynomická funkce: žádná asymptota",
"Der Zähler hat einen kleineren Grad als der Nenner: Es gibt nichts zu teilen.": "Čitatel má nižší stupeň než jmenovatel: není co dělit.",
"<0>Nenner null setzen:</0> Dort ist die Funktion nicht definiert.": "<0>Polož jmenovatel roven nule:</0> tam funkce není definována.",
"Der Nenner wird für keine reelle Zahl null: Die Funktion ist überall definiert.": "Jmenovatel není nulový pro žádné reálné číslo: funkce je definována všude.",
"Der Nenner ist eine Zahl: Das ist eine ganzrationale Funktion ohne Definitionslücken.": "Jmenovatel je číslo: je to polynomická funkce definovaná všude.",
"<0>Stelle</0> {1}: Der Zähler ist dort nicht null.": "<0>Pro</0> {1}: čitatel tam není nulový.",
"<0>Stelle</0> {1}: Auch der Zähler ist dort null. Der gemeinsame Faktor {2} lässt sich kürzen.": "<0>Pro</0> {1}: čitatel je tam také nulový. Společný činitel {2} lze zkrátit.",
"<0>Stelle</0> {1}: Zähler und Nenner sind beide null, aber der Nenner öfter. Nach dem Kürzen bleibt der Faktor im Nenner stehen.": "<0>Pro</0> {1}: čitatel i jmenovatel jsou nulové, ale jmenovatel vícekrát. Po zkrácení zůstane činitel ve jmenovateli.",
"Polstelle mit Vorzeichenwechsel: Der Graph verschwindet auf der einen Seite nach oben, auf der anderen nach unten.": "Pól se změnou znaménka: na jedné straně graf utíká nahoru, na druhé dolů.",
"Polstelle ohne Vorzeichenwechsel: Der Nenner hat hier eine doppelte Nullstelle, der Graph verschwindet auf beiden Seiten in dieselbe Richtung.": "Pól beze změny znaménka: jmenovatel zde má dvojnásobný nulový bod, graf utíká na obou stranách stejným směrem.",
"Polstelle mit Vorzeichenwechsel.": "Pól se změnou znaménka.",
"Polstelle ohne Vorzeichenwechsel.": "Pól beze změny znaménka.",
"Hebbare Lücke: Im Graphen fehlt nur der Punkt {0}.": "Odstranitelná nespojitost: v grafu chybí jen bod {0}.",
"<0>Gekürzter Term:</0> Er stimmt ausserhalb der Lücken mit {1} überein.": "<0>Zkrácený výraz:</0> mimo vyloučené body se shoduje s {1}.",
"<0>Nullstellen:</0> Der Zähler ist null, der Nenner nicht.": "<0>Nulové body:</0> čitatel je nulový, jmenovatel ne.",
"Es gibt keine Nullstellen.": "Nulové body neexistují.",
"Der Zähler ist überall null: Die Funktion hat ausserhalb der Lücken überall den Wert {0}.": "Čitatel je všude nulový: mimo vyloučené body má funkce všude hodnotu {0}.",
"Polstellen: {0}, hebbare Lücken: {1}, Nullstellen: {2}": "Póly: {0}, odstranitelné nespojitosti: {1}, nulové body: {2}",
"Keine Definitionslücken, Nullstellen: {0}": "Žádné vyloučené body, nulové body: {0}",
"<0>Grade vergleichen:</0> Der Zähler hat den Grad {1}, der Nenner den Grad {2}.": "<0>Porovnej stupně:</0> čitatel má stupeň {1}, jmenovatel stupeň {2}.",
"Der Nenner ist eine Zahl: Das ist eine ganzrationale Funktion. Sie hat keine Asymptote.": "Jmenovatel je číslo: je to polynomická funkce. Nemá asymptotu.",
"<0>Zählergrad kleiner:</0> Für grosse {1} wächst der Nenner schneller als der Zähler, der Bruch geht gegen {2}.": "<0>Stupeň čitatele menší:</0> pro velká {1} roste jmenovatel rychleji než čitatel, zlomek se blíží k {2}.",
"<0>Gleicher Grad:</0> Für grosse {1} zählen nur die höchsten Potenzen; ihr Verhältnis ist der Grenzwert.": "<0>Stejný stupeň:</0> pro velká {1} rozhodují jen nejvyšší mocniny; jejich poměr je limita.",
"<0>Zählergrad um eins grösser:</0> Die Polynomdivision spaltet eine Gerade ab, die schiefe Asymptote.": "<0>Stupeň čitatele o jedna větší:</0> dělení mnohočlenů oddělí přímku, šikmou asymptotu.",
"<0>Zählergrad um mehr als eins grösser:</0> Die Polynomdivision spaltet eine ganzrationale Funktion ab; an ihren Graphen schmiegt sich die Kurve.": "<0>Stupeň čitatele větší o více než jedna:</0> dělení mnohočlenů oddělí polynomickou funkci; křivka se přimyká k jejímu grafu.",
"<0>Zerlegung:</0> ganzrationaler Teil plus Restbruch. Der Restbruch geht für grosse {1} gegen {2}.": "<0>Rozklad:</0> polynomická část plus zbytkový zlomek. Zbytkový zlomek se pro velká {1} blíží k {2}.",
"Die Division geht ohne Rest auf: Ausserhalb der Lücken ist der Graph genau diese Gerade.": "Dělení vyjde beze zbytku: mimo vyloučené body je graf přesně tato přímka.",
"Die Division geht ohne Rest auf: Ausserhalb der Lücken ist der Graph genau diese Kurve.": "Dělení vyjde beze zbytku: mimo vyloučené body je graf přesně tato křivka.",
"<0>Abstand zur Asymptote</0> an der Stelle {1}: Funktionswert minus Wert der Asymptote.": "<0>Vzdálenost od asymptoty</0> pro {1}: hodnota funkce minus hodnota asymptoty.",
"<0>Schritt {1}:</0> höchste Potenzen teilen, zurückmultiplizieren, abziehen.": "<0>Krok {1}:</0> vyděl nejvyšší mocniny, vynásob zpět, odečti.",
"<0>Ende:</0> Der Rest hat einen kleineren Grad als der Nenner. Er bleibt als Bruch stehen.": "<0>Konec:</0> zbytek má nižší stupeň než jmenovatel. Zůstane jako zlomek.",
"<0>Ende:</0> Der Rest ist {1}, die Division geht auf.": "<0>Konec:</0> zbytek je {1}, dělení vyjde beze zbytku.",
"<0>Probe:</0> Quotient mal Nenner plus Rest ergibt den Zähler.": "<0>Zkouška:</0> podíl krát jmenovatel plus zbytek dává čitatel.",
"Quotient {0}, Rest {1}": "Podíl {0}, zbytek {1}",
"Der Zähler hat einen kleineren Grad als der Nenner: Es gibt nichts zu teilen, der Bruch ist schon der Rest.": "Čitatel má nižší stupeň než jmenovatel: není co dělit, zlomek už je zbytkem.",
"{0} bleibt, wie es ist": "{0} zůstane, jak je",
