"Es gibt weder Nullstellen noch Definitionslücken: Die Funktion hat überall dasselbe Vorzeichen.": "Neexistují nulové body ani vyloučené body: funkce má všude stejné znaménko.",
"Bei {0} liegt eine doppelte Nullstelle: Der Graph berührt die x-Achse, das Vorzeichen bleibt.": "Pro {0} je dvojnásobný nulový bod: graf se dotýká osy x, znaménko zůstává.",
"Bei {0} liegt eine Polstelle ohne Vorzeichenwechsel.": "Pro {0} je pól beze změny znaménka.",
